  add('limit','Limit','calculus',['lim','L'],'The value a function approaches near an input, when the stated one-sided or two-sided conditions hold. The value at the input may differ or be missing.','lim as x→1 of (x+1) is 2.','limit',['limits','approach'],{tokens:['lim','L'],sourceKeys:['limits'],mathSymbols:['\\lim']});
  add('continuity','Continuity','calculus',[],'At a point, the function is defined and its nearby limit equals that point’s value.','f(x)=x+1 is continuous at x=1.','continuity',['continuous','discontinuity'],{sourceKeys:['limits']});
  add('one-sided-limit','One-sided limit and probes','calculus',[],'A limit from inputs on only one side of a point. Finite nearby readings are probes, not themselves proof of a limit.','A jump can approach 0 from the left and 2 from the right.','left-hand or right-hand limit',['left limit','right limit','probe','one sided'],{tokens:['leftValue','rightValue'],sourceKeys:['limits']});
  add('derivative','Derivative','calculus',['f′(a)','dy/dx'],'An instantaneous rate defined by a limit of difference quotients, when that limit exists.','For f(x)=x², f′(3)=6.','f prime at a',['derivatives','differentiation','prime'],{tokens:['f′(a)'],sourceKeys:['derivative'],mathSymbols:['\\frac{d','f′']});
  add('secant','Secant line','calculus',[],'A line through two points of a graph; its slope gives a finite average rate between them.','The secant of x² from 1 to 2 has slope 3.','secant',['secants','average rate'],{sourceKeys:['derivative']});
  add('tangent','Tangent line','calculus',[],'A line describing local first-order behavior at a point when a finite derivative exists.','The tangent to x² at 1 has slope 2.','tangent',['tangent line','analytic slope'],{sourceKeys:['derivative']});
  add('rate','Rate of change','calculus',[],'A change in one quantity per unit change in another; its units identify the comparison.','2 metres per second is a distance rate.','rate',['rate of change','rate'],{tokens:['rate'],sourceKeys:['derivative']});
  add('increment','Increment','calculus',['h'],'A signed finite change added to an input. A zero increment cannot be used as the divisor of a difference quotient.','From a=2, h=0.1 gives a+h=2.1.','step h',['step','increment','run'],{tokens:['h'],sourceKeys:['derivative']});
  add('integral','Definite integral','calculus',['∫'],'A limit of signed sums over an interval, when it exists. It can represent net accumulation with the integrand’s units multiplied by input units.','∫₀² 3 dt = 6','integral',['integration','integrals','accumulation'],{sourceKeys:['integral'],mathSymbols:['∫','\\int']});
  add('integrand','Integrand','calculus',[],'The expression being integrated.','In ∫₀² 3t dt, the integrand is 3t.','integrand',['integrands'],{sourceKeys:['integral']});
  add('partition','Partition','calculus',[],'A division of an interval into smaller intervals, used to form a finite sum.','Split [0,4] into 8 intervals of width 0.5.','partition',['partitions','rectangle count','subinterval'],{tokens:['partitions'],sourceKeys:['integral']});
  add('riemann-sum','Riemann sum','calculus',['Σ f(xᵢ)Δx'],'A finite sum of function values times interval widths; the sample-point rule matters.','A left-endpoint sum samples each interval at its left edge.','sum of sampled heights times widths',['left sum','right sum','midpoint sum','finite sum'],{tokens:['L_n'],sourceKeys:['integral']});
  add('displacement','Displacement','calculus',['S(T)'],'The signed change in position between the start and end of a motion.','Move 2 m forward and 2 m back: displacement is 0 m.','displacement',['net displacement','signed area'],{tokens:['S(T)'],sourceKeys:['integral']});
  add('distance-travelled','Distance travelled','calculus',['D(T)'],'The nonnegative total path length, counting travel in either direction positively.','Move 2 m forward and 2 m back: distance is 4 m.','total distance',['distance traveled','total distance'],{tokens:['D(T)'],sourceKeys:['integral']});
  add('partial-derivative','Partial derivative','calculus',['∂'],'A derivative with respect to one input of a several-input function while the other independent inputs are held fixed.','For f(x,y)=x²+y, ∂f/∂x=2x.','partial',['partial','partial derivatives'],{sourceKeys:['derivative'],mathSymbols:['∂','\\partial']});
  add('gradient','Gradient','calculus',['∇f'],'The vector of a scalar function’s partial derivatives, where they are defined.','For f(x,y)=x²+y², ∇f=(2x,2y).','grad f',['gradient','nabla'],{sourceKeys:['dot'],mathSymbols:['∇','\\nabla']});
  add('probability','Probability','chance',['p','P(A)'],'A number from 0 to 1 describing an event’s chance under a stated model.','A fair coin has P(heads)=1/2.','probability of A',['probabilities','chance'],{tokens:['p']});
  add('event','Event','chance',[],'A set of outcomes whose probability is being considered.','Rolling an even number is the event {2,4,6}.','event',['events']);
  add('outcome','Outcome','chance',[],'One possible result of a random experiment. An event can contain one or several outcomes.','Rolling a 4 is one outcome of a die roll.','outcome',['outcomes']);
  add('sample-space','Sample space','chance',['Ω'],'The set of all possible outcomes in a stated random experiment.','For one ordinary die roll, the sample space is {1,2,3,4,5,6}.','sample space',['sample spaces'],{mathSymbols:['Ω']});
  add('conditional-probability','Conditional probability','chance',['P(A|B)'],'The probability of A when attention is restricted to outcomes in B; P(B) must be positive for the elementary ratio definition.','Among flagged parts, what fraction are defective?','probability of A given B',['given','conditional'],{mathSymbols:['P(A|B)','P(A\\mid B)']});
  add('independence','Independence','chance',[],'Events are independent when knowing one occurred does not change the probability of the other, with the usual probability-product definition.','Independent fair coin tosses retain head probability 1/2.','independence',['independent','independent trials']);
  add('random-variable','Random variable','chance',['X'],'A numerical value assigned to each outcome of a random experiment.','X can count successes in six trials.','random variable X',['random variables'],{tokens:['X']});
  add('expected-value','Expected value','chance',['E[X]'],'A probability-weighted mean of a random variable, not a guarantee about one observation.','Six trials with success chance 1/2 have expected count 3.','expected value of X',['expectation','mean','average'],{tokens:['E[X]'],sourceKeys:['expectation']});
  add('variance','Variance','chance',['Var(X)'],'The expected squared difference from a random variable’s mean. Its units are squared.','A Bernoulli variable with chance p has variance p(1−p).','variance of X',['variance'],{sourceKeys:['expectation']});
  add('prior','Prior probability','chance',[],'A probability assigned before the particular new information is incorporated.','A prior defect probability can be 0.1.','prior',['prior'],{tokens:['prior']});
  add('posterior','Posterior probability','chance',[],'A conditional probability after incorporating the specified information.','A posterior defect chance conditions on a flag.','posterior',['posterior','bayes theorem'],{tokens:['posterior']});
  add('sensitivity','Sensitivity','chance',[],'The probability of a positive flag given the condition being detected. It is not the chance of the condition given a flag.','Sensitivity 0.9 means P(flag | defect)=0.9.','sensitivity',['true positive rate'],{tokens:['sensitivity']});
  add('false-positive','False-positive probability','chance',[],'The probability of a positive flag when the condition is absent.','A false-positive rate 0.05 means P(flag | no defect)=0.05.','false positive',['false alarm'],{tokens:['falsePositive']});
  add('iteration','Iteration','dynamics',[],'Apply a rule repeatedly, using one result as the next input.','Start at x₀, then compute x₁=f(x₀), x₂=f(x₁).','iteration',['iterate','iterations','recurrence','generation'],{wordMatches:['iteration','iterate','recurrence']});
  add('perturbation','Perturbation','dynamics',[],'A change made to an input or state to inspect how the result responds.','Compare starting values 0.4 and 0.4001.','perturbation',['perturbations','initial separation']);
  add('chaos','Chaos','dynamics',[],'In deterministic dynamics, sensitive behavior can make nearby starts separate strongly under iteration. A single separating pair is an illustration, not a complete chaos test.','Compare nearby starts in a fixed logistic rule.','chaos',['chaotic','chaos theory']);
  add('fractal','Fractal','dynamics',[],'A structure with fine-scale detail often studied through repeated construction or scale relations. A finite drawing shows only finitely many levels.','A Koch construction replaces each segment by four smaller ones.','fractal',['fractals','fractal geometry']);
  add('self-similarity','Self-similarity','dynamics',[],'A relation in which a part resembles the whole after an appropriate change of scale; exact and approximate versions differ.','A Koch side contains smaller copies of its construction.','self similarity',['self similar','self-similar']);
  add('phase','Phase','dynamics',[],'A position within an oscillation cycle, often measured by an angle. Relative phase compares two cycles.','A phase difference π puts equal sinusoidal waves in opposition.','phase',['phase shift','relative phase'],{sourceKeys:['trig']});
  add('amplitude','Amplitude','dynamics',['A'],'A nonnegative size parameter for an oscillation measured from its reference level.','In y=A sin(t), |A| is the amplitude.','amplitude',['amplitudes','resultant amplitude'],{tokens:['A','amplitude'],sourceKeys:['trig']});
  add('frequency','Frequency','dynamics',[],'How often cycles occur per unit time; angular frequency instead measures radians per unit time.','2 Hz means two cycles per second.','frequency',['angular frequency','hertz'],{tokens:['frequency'],sourceKeys:['trig']});
  add('resonance','Resonance','dynamics',[],'A strong response of a driven system near an appropriate natural rate; damping changes the response and its peak.','A damped oscillator responds differently as drive frequency changes.','resonance',['resonant','driven oscillator']);
  add('damping','Damping','dynamics',[],'A mechanism or model term that reduces oscillatory motion or response, often through dissipation.','A larger damping ratio reduces a sharp response peak.','damping',['damping ratio'],{tokens:['damping']});
  add('vector','Vector','linear',['u','v'],'A quantity described by components in the geometric setting used here. A nonzero vector has magnitude and direction; the zero vector has magnitude zero and no unique direction.','u=(3,4) has length 5.','vector',['vectors'],{sourceKeys:['vectors']});
  add('scalar','Scalar','linear',[],'A single numerical value used by the current vector or matrix setting.','Multiplying (1,2) by scalar 3 gives (3,6).','scalar',['scalars'],{sourceKeys:['vectors']});
  add('component','Component','linear',[],'One coordinate of a vector relative to a chosen basis or axes.','The horizontal component of (3,4) is 3.','component',['components','horizontal component','vertical component'],{sourceKeys:['vectors']});
  add('magnitude','Magnitude or norm','linear',['‖v‖'],'A nonnegative size assigned to a vector. Here the Euclidean norm is the square root of the sum of squared components.','‖(3,4)‖ = 5','norm of v',['norm','length of a vector','magnitude'],{sourceKeys:['vectors'],mathSymbols:['‖','\\lVert']});
  add('unit-vector','Unit vector','linear',[],'A vector whose norm is 1. A nonzero vector can be divided by its norm to form one in the same direction.','(3/5,4/5) is a unit vector.','unit vector',['unit vectors','normalize'],{sourceKeys:['vectors']});
  add('dot-product','Dot product','linear',['u·v','⟨u,v⟩'],'For real Euclidean vectors, multiply corresponding components and add. The result is a scalar.','(1,2)·(3,4) = 11','u dot v',['inner product','scalar product','dot'],{sourceKeys:['dot']});
  add('projection','Projection','linear',[],'The component of a vector along a chosen direction. Projection onto the zero vector is not defined by the usual division formula.','The projection of (3,4) onto the horizontal axis is (3,0).','projection',['project','projected'],{sourceKeys:['dot']});
  add('orthogonal','Orthogonal','linear',['⊥'],'Euclidean vectors are orthogonal when their dot product is zero, including the zero vector. For two nonzero vectors, this means their directions form a right angle.','(1,0)·(0,1)=0','perpendicular',['perpendicular','orthogonality'],{sourceKeys:['dot'],mathSymbols:['⊥','\\perp']});
  add('matrix','Matrix','linear',['A','B'],'A rectangular array of entries, with row and column order affecting its operations. A row runs horizontally and a column vertically; each position contains an entry.','[[1,2],[0,1]] has two rows and two columns.','matrix',['matrices','matrix entries'],{tokens:['A','B'],sourceKeys:['matrix']});
  add('linear-map','Linear map','linear',['Av'],'A transformation preserving vector addition and scalar multiplication. A matrix acts linearly by multiplying a component vector.','A(u+v)=Au+Av','A times v',['linear transformation','linear map','matrix transformation'],{sourceKeys:['matrix']});
  add('determinant','Determinant','linear',['det(A)','det(B)'],'A scalar associated with a square matrix. For a real 2D linear map it gives signed area scale: its sign tracks orientation and zero means area collapses.','det([[a,b],[c,d]]) = ad−bc','determinant',['det','signed area scale'],{tokens:['det(A)','det(B)','determinant'],sourceKeys:['determinant']});
  add('singular','Singular matrix','linear',[],'A square matrix without an inverse; equivalently, its determinant is zero. It still defines a valid linear transformation.','[[1,2],[2,4]] is singular.','singular',['singular matrix','collapse'],{sourceKeys:['determinant']});
  add('identity-matrix','Identity matrix','linear',['I'],'A square matrix that leaves a compatible vector unchanged when multiplied by it.','[[1,0],[0,1]](x,y)=(x,y)','identity matrix',['identity matrix'],{sourceKeys:['matrix']});
  add('complex-number','Complex number','linear',['a+bi'],'A number a+bi with real a,b and i²=−1. It can be represented as a point or arrow in a plane. Real numbers are included when b=0.','(2+i)(1+i)=1+3i','a plus b i',['complex','complex numbers'],{sourceKeys:['complex']});
  add('imaginary-unit','Imaginary unit','linear',['i'],'The number i is defined so that i²=−1. It supplies the imaginary direction when writing a complex number a+bi.','i·i = −1','i',['imaginary unit'],{sourceKeys:['complex'],tokens:['i'],grammarCards:['complex-multiplication'],mathSymbols:['i²','i^2']});
  add('pure-imaginary-number','Pure imaginary number','linear',['bi'],'A complex number with zero real part and a nonzero imaginary coefficient. Here b is real and b≠0.','3i is pure imaginary; 2+3i is not.','b i',['pure imaginary','imaginary number'],{sourceKeys:['complex']});
  add('real-part','Real part','linear',['Re(z)'],'The real coefficient a in a complex number a+bi.','Re(2+3i)=2','real part of z',['real part'],{tokens:['real','realPart'],sourceKeys:['complex']});
  add('imaginary-part','Imaginary part','linear',['Im(z)'],'The real coefficient b of i in a complex number a+bi.','Im(2+3i)=3','imaginary part of z',['imaginary part'],{tokens:['imag','imagPart'],sourceKeys:['complex']});
  add('alpha','Alpha','greek',['α'],'The Greek letter alpha. It can label an angle, coefficient or another defined quantity; its role must be stated.','An author may set angle α = 30°.','alpha',['alpha']);
  add('beta','Beta','greek',['β'],'The Greek letter beta. It is a label whose mathematical meaning depends on context.','An author may use β for a second angle.','beta',['beta']);
  add('gamma','Gamma','greek',['γ'],'The Greek letter gamma, used for various defined parameters or quantities. Capital Γ is a different symbol.','A model might define γ as a decay parameter.','gamma',['gamma']);
  add('delta-small','Small delta','greek',['δ'],'A lowercase Greek letter. In a limit definition it can bound input distance; in the chaos card it is an initial perturbation. These are context-specific meanings.','0 < |x−a| < δ bounds a nearby input distance.','delta',['delta','small delta','lowercase delta'],{sourceKeys:['greek','limits'],mathSymbols:['δ','\\delta']});
  add('delta-capital','Capital delta — change','greek',['Δ'],'Capital Greek delta often marks a finite change, found by subtracting an old value from a new one. It is distinct from lowercase δ and partial ∂.','Δf = f(a+h)−f(a)','capital delta',['delta','capital delta','change in'],{sourceKeys:['greek','derivative'],mathSymbols:['Δ','\\Delta']});
  add('epsilon','Epsilon','greek',['ε','ϵ'],'A Greek letter often used for a positive error tolerance in a limit definition. Its precise role must be defined.','|f(x)−L| < ε bounds output error.','epsilon',['epsilon','varepsilon','tolerance'],{sourceKeys:['greek','limits'],mathSymbols:['ε','ϵ','\\epsilon','\\varepsilon']});
  add('zeta','Zeta','greek',['ζ'],'The Greek letter zeta. In the resonance setting it names a dimensionless damping ratio.','The oscillator can use ζ = 0.2.','zeta',['zeta'],{mathSymbols:['ζ','\\zeta']});
  add('eta','Eta','greek',['η'],'The Greek letter eta. It can name a parameter or quantity, with its meaning specified by the surrounding problem.','A model may define efficiency η = useful output / input.','eta',['eta'],{mathSymbols:['η','\\eta']});
  add('theta','Theta','greek',['θ','ϑ'],'A Greek letter commonly used to label an angle; check whether its unit is degrees or radians.','The rotation card measures θ in degrees.','theta',['theta','vartheta'],{sourceKeys:['greek','trig'],tokens:['θ'],mathSymbols:['θ','ϑ','\\theta']});
  add('iota','Iota','greek',['ι'],'The Greek letter iota. It is a mathematical label whose meaning must be supplied in context; it is different from the Latin letter i.','An author may name a map ι and then define what it does.','iota',['iota'],{mathSymbols:['ι','\\iota']});
  add('kappa','Kappa','greek',['κ','ϰ'],'The Greek letter kappa. It may label a constant, curvature, or another declared quantity; those uses are different contexts.','A geometry problem might define curvature κ = 1/r for a circle of radius r.','kappa',['kappa','varkappa'],{mathSymbols:['κ','ϰ','\\kappa','\\varkappa']});
  add('lambda','Lambda','greek',['λ'],'The Greek letter lambda, used for quantities such as eigenvalues or wavelengths when defined in that context.','Av = λv uses λ as an eigenvalue.','lambda',['lambda','lamda']);
  add('mu','Mu','greek',['μ'],'A Greek letter often used for a population mean or another declared parameter. It has no single universal mathematical value.','A probability model may define μ = E[X].','mu',['mu'],{sourceKeys:['greek','expectation']});
  add('nu','Nu','greek',['ν'],'The Greek letter nu. It can name a frequency or another defined quantity. It is a different character from the Latin letter v.','An author may write ν = 2 cycles per second after defining ν as frequency.','nu',['nu'],{mathSymbols:['ν','\\nu']});
  add('xi','Xi','greek',['ξ'],'The Greek letter xi. It is used as a label for a variable or quantity whose meaning depends on the problem.','One can define ξ = x−a to name an offset from a.','xi',['xi'],{mathSymbols:['ξ','\\xi']});
  add('omicron','Omicron','greek',['ο'],'The Greek letter omicron, visually similar to the Latin letter o. It has no universal mathematical value or operation.','If a text names a quantity ο, its definition must explain that choice.','omicron',['omicron'],{mathSymbols:['ο']});
  add('pi','Pi','greek',['π'],'The constant equal to a circle’s circumference divided by its diameter, in Euclidean geometry.','A half turn equals π radians.','pi',['pi'],{sourceKeys:['greek','trig'],mathSymbols:['π','\\pi']});
  add('rho','Rho','greek',['ρ'],'The Greek letter rho, used for quantities such as density or correlation when those are defined.','A model may define ρ = mass/volume.','rho',['rho']);
  add('sigma-small','Small sigma','greek',['σ','ς'],'The lowercase Greek letter sigma; in probability it often denotes a standard deviation. The final-letter form ς is a variant. It is distinct from capital Σ.','σ = √Var(X) in a probability model.','sigma',['sigma','small sigma','standard deviation','varsigma'],{sourceKeys:['greek','expectation'],mathSymbols:['σ','ς','\\sigma','\\varsigma']});
  add('summation','Capital sigma — summation','greek',['Σ','∑'],'A notation for adding terms indexed over a stated range. The index and its bounds specify which terms enter the sum.','Σ from k=1 to 3 of k = 1+2+3 = 6.','sum',['sigma','capital sigma','summation'],{sourceKeys:['greek','integral'],mathSymbols:['Σ','∑','\\sum']});
  add('tau','Tau','greek',['τ'],'The Greek letter tau. It can name a time constant, a parameter, or another declared quantity; no single meaning applies to every use.','A decay model may define τ as the time scale in e^(−t/τ).','tau',['tau'],{mathSymbols:['τ','\\tau']});
  add('upsilon','Upsilon','greek',['υ'],'The Greek letter upsilon. Its mathematical role is assigned in the text using it. It is distinct from the Latin letter u.','An author may define a function υ(x), then specify its rule.','upsilon',['upsilon'],{mathSymbols:['υ','\\upsilon']});
  add('phi','Phi','greek',['φ','ϕ'],'A Greek letter often used for an angle or relative phase. Different conventions may assign it other meanings.','The wave card uses φ for relative phase in radians.','phi',['phi','varphi'],{sourceKeys:['greek','trig'],tokens:['φ'],mathSymbols:['φ','ϕ','\\phi']});
  add('chi','Chi','greek',['χ'],'The Greek letter chi. It can label a variable or a particular defined function; the surrounding text supplies its meaning.','An author may define χ_A(x)=1 when x belongs to A and 0 otherwise.','chi',['chi'],{mathSymbols:['χ','\\chi']});
  add('psi','Psi','greek',['ψ'],'The Greek letter psi. It can name a function or another quantity after that role has been defined.','An author can define ψ(x)=x² as a named function.','psi',['psi'],{mathSymbols:['ψ','\\psi']});
  add('omega','Omega','greek',['ω'],'The lowercase Greek letter omega; in oscillation settings it often represents angular frequency.','For frequency f, angular frequency can be ω=2πf.','omega',['omega','angular frequency'],{sourceKeys:['greek','trig'],mathSymbols:['ω','\\omega']});
  add('proof','Proof','language',[],'A logical argument establishing a mathematical claim from stated assumptions and accepted results. Checking examples alone is not a proof.','An identity can be proved by expanding both sides.','proof',['prove','proved','proving'],{sourceKeys:['logic']});
  add('counterexample','Counterexample','language',[],'An allowed example that makes a claimed universal statement false. One counterexample is enough to refute that statement.','x=0 refutes the claim that every real x is positive.','counterexample',['counterexamples','refute'],{sourceKeys:['logic']});
  add('analytic','Analytic calculation','calculus',[],'In these cards, a value obtained from an exact stated mathematical formula rather than inferred from a finite plot or estimated slope. The technical term analytic function has a different, more specific meaning.','For x³, the derivative formula is 3x².','analytic',['analytic slope','analytic derivative'],{sourceKeys:['derivative']});
  add('orientation','Orientation','linear',[],'A choice of handedness or ordered direction. A real plane linear map with negative determinant reverses orientation; positive determinant preserves it.','Reflecting a square across an axis reverses its orientation.','orientation',['orientation reversal','orientation preserving'],{sourceKeys:['determinant']});
  add('inverse-matrix','Inverse matrix','linear',['A⁻¹'],'A matrix that undoes multiplication by a square matrix; it exists exactly when the square matrix is nonsingular.','If A scales both coordinates by 2, A⁻¹ scales them by 1/2.','A inverse',['matrix inverse','invertible','nonsingular'],{sourceKeys:['matrix','determinant']});
  add('basis','Basis','linear',['B'],'A linearly independent collection of vectors spanning the space. An ordered basis fixes their order and gives every vector a unique coordinate list. Vectors need not have unit length or be perpendicular; nonperpendicular directions give an oblique basis.','((1,0),(0,1)) is the standard plane basis; ((2,0),(1,1)) is another.','basis',['basis vectors','ordered basis','standard basis'],{tokens:['B'],grammarCards:['basis'],sourceKeys:['basis','coordinates']});
  add('undefined','Undefined','language',[],'An expression has no value under its stated mathematical setting or current inputs; this is different from a value of zero.','1/0 is undefined in real arithmetic.','undefined',['not defined','does not exist'],{sourceKeys:['numbers','limits']});
  add('units','Units','language',[],'Reference quantities attached to measurements; operations must respect what those measurements mean.','Velocity in m/s multiplied by seconds gives displacement in m.','units',['unit','dimension','dimensional'],{sourceKeys:['vectors','integral']});
  add('sign','Sign: positive, negative and zero','operations',[],'A positive real number is above zero; a negative one is below zero. Nonnegative includes zero, while nonzero excludes it.','−2 is negative; 0 is nonnegative but not positive.','sign',['signed','positive','negative','nonnegative','nonzero'],{sourceKeys:['numbers']});
  add('finite','Finite','language',[],'Having a bounded numerical value or a limited count, according to context. A finite sample contains only finitely many observations.','Nine sampled inputs form a finite table.','finite',['finitely many'],{sourceKeys:['numbers','limits']});
  add('dimensionless','Dimensionless quantity','language',[],'A quantity whose physical dimensions cancel, such as a ratio of two lengths measured in compatible units. It still has a mathematical meaning.','6 m / 3 m = 2 is a dimensionless scale factor.','dimensionless',['unitless'],{sourceKeys:['vectors']});
  add('interpolation','Interpolation','functions',[],'Construct an intermediate value between specified values using a stated rule. An interpolated display is not automatically a new discrete iteration.','Halfway between 2 and 6, linear interpolation gives 4.','interpolation',['interpolate','interpolated','morph']);
  add('commutative','Commutative operation','language',[],'An operation is commutative when swapping its two inputs preserves the result for all allowed pairs.','a+b=b+a for real numbers; some matrix pairs also commute.','commutative',['commute','commutativity'],{sourceKeys:['numbers','matrix']});
  add('distributive','Distributive property','language',[],'A relation between multiplication and addition that allows a multiplier to act on each term of a sum.','a(b+c)=ab+ac for real numbers.','distributive',['distribute','distributivity'],{sourceKeys:['numbers']});
  add('polynomial','Polynomial','functions',[],'A finite sum of terms made from coefficients and nonnegative whole powers of variables.','3x²−2x+1 is a polynomial.','polynomial',['polynomials'],{sourceKeys:['powers']});
  add('invariant','Invariant','language',[],'A property or quantity preserved by a stated transformation or process. The process and conditions must be specified.','A Euclidean rotation preserves a vector’s length.','invariant',['invariance','preserved'],{sourceKeys:['vectors']});
  add('linear-independence','Linear independence','linear',[],'Vectors are linearly independent when the only linear combination producing zero uses zero for every coefficient.','The plane vectors (1,0) and (0,1) are independent.','linear independence',['linearly independent','independent vectors','independent pair'],{wordMatches:['linear independence','linearly independent','independent vectors','independent pair','independent plane directions','independent arrows','independent spanning collection','independence assumption'],sourceKeys:['basis']});
  add('linear-dependence','Linear dependence','linear',[],'Vectors are linearly dependent when some linear combination producing zero has at least one nonzero coefficient.','(1,2) and (2,4) are dependent because 2(1,2)−(2,4)=(0,0).','linear dependence',['linearly dependent','dependent vectors','dependent pair'],{sourceKeys:['basis']});
  add('linear-combination','Linear combination','linear',['ru+sv'],'A finite sum of vectors multiplied by scalar coefficients. In these real-vector cards the coefficients can be negative, zero or positive; they need not add to one.','2(1,0)−3(0,1)=(2,−3).','r times u plus s times v',['linear combinations','weighted vector sum'],{tokens:['ru+sv','r u+s v'],sourceKeys:['subspaces']});
  add('weight','Weight in a linear combination','linear',[],'A scalar coefficient multiplying one vector in a linear combination. This algebraic weight is not necessarily a probability, a mass or a positive fraction.','In 2u−3v, the weight on v is −3.','weight',['weights','weighted'],{tokens:['r','s'],grammarCards:['linear-combination'],wordMatches:['weight','weights','weighted'],sourceKeys:['subspaces']});
  add('vector-addition','Vector addition','linear',['u+v'],'Add corresponding components in a common coordinate system. Geometrically, the second displacement can start at the first arrow’s tip.','(1,2)+(3,−1)=(4,1).','u plus v',['add vectors','adding vectors','vector sum'],{sourceKeys:['vectors'],tokens:['u+v']});
  add('scalar-multiplication','Scalar multiplication','linear',['ru'],'Multiply every vector component by the same scalar. A negative real scalar reverses a nonzero vector’s direction; zero produces the zero vector.','−2(1,3)=(−2,−6).','r times u',['scalar multiple','scalar multiples','scale a vector'],{sourceKeys:['vectors'],tokens:['ru']});
  add('span','Span','linear',['span(u,v)'],'All vectors obtainable as linear combinations of the given vectors using every allowed coefficient value. These cards use all real coefficients; fixed slider bounds display only part of that span.','span((1,0),(0,1)) is the whole real plane.','span of u and v',['spanning','spans','linear span'],{sourceKeys:['basis'],tokens:['span(u,v)','span']});
  add('subspace','Vector subspace','linear',[],'A subset including zero in which adding any two members or multiplying a member by any allowed scalar stays in the subset. A line through the origin is a subspace of the plane; a shifted parallel line is not.','All vectors (t,0), with real t, form a subspace of the plane.','subspace',['subspaces','vector subspace'],{wordMatches:['subspace','subspaces'],sourceKeys:['subspaces']});
  add('coordinate-vector','Coordinates in a basis','linear',['[v]_B'],'The ordered coefficients expressing a vector in an ordered basis. Changing the basis can change these numbers while the vector stays the same.','For B=((2,0),(1,1)), v=(3,1) has basis coordinates (1,1).','coordinates of v in basis B',['basis coordinates','coordinate vector','coordinate list'],{tokens:['r','s','[v]_B'],grammarCards:['basis'],sourceKeys:['coordinates']});
  add('change-of-basis','Change of basis','linear',[],'Rewrite the same vector using a different ordered basis. A coordinate-conversion matrix changes its coordinate list; this alone does not move the geometric vector.','The vector (3,1) has coordinates (1,1) in B=((2,0),(1,1)).','change of basis',['change of coordinates','change-of-basis','coordinate conversion','changing basis'],{sourceKeys:['coordinates']});
  add('rank','Matrix rank','linear',['rank(A)','rank(B)'],'The maximum number of linearly independent columns of a matrix, equal to the dimension of its output span. For a real plane map, rank 0, 1 or 2 corresponds to point, line or plane output.','[[1,2],[2,4]] has rank 1.','rank',['rank'],{tokens:['rank','rank(A)','rank(B)'],wordMatches:['rank','matrix rank'],sourceKeys:['rank','basis']});
  add('matrix-product','Matrix product','linear',['AB','BA'],'Multiply compatible matrices by taking each left row’s dot product with each right column. For column vectors, AB acts as A(Bv): the rightmost matrix acts first. This product is not entry-by-entry multiplication.','A=[[1,1],[0,1]], B=[[1,0],[1,1]] give AB=[[2,1],[1,1]].','A times B (AB); B times A (BA)',['A times B','B times A','matrix multiplication','matrix composition','product of matrices','rightmost first'],{tokens:['AB','BA'],grammarCards:['matrix-product'],sourceKeys:['matrix']});
  add('associative','Associative operation','language',[],'An operation is associative when regrouping three inputs preserves the result without changing their order. Compatible matrix products satisfy this rule.','(AB)C=A(BC), while AB need not equal BA.','associative',['associativity','regrouping'],{sourceKeys:['matrix']});
  add('reconstruction','Vector reconstruction','linear',[],'Recover a vector by multiplying its basis vectors by its coordinate coefficients and adding. Correct coordinates in a basis reconstruct the original vector.','1(2,0)+1(1,1)=(3,1).','reconstruction',['reconstruct','reconstructed','reconstructing'],{wordMatches:['reconstruction','reconstruct','reconstructed','reconstructing'],sourceKeys:['coordinates']});
  add('shear','Shear','linear',[],'A linear slant in which one coordinate changes by a multiple of the other while that other coordinate stays fixed. The horizontal and vertical plane shears here preserve signed area.','A horizontal shear (x,y)↦(x+2y,y) takes (1,1) to (3,1).','shear',['shears','shearing','horizontal shear','vertical shear'],{sourceKeys:['shears']});
  add('noncommutative','Noncommutative operation','language',[],'An operation is noncommutative when swapping inputs can change the result. It does not mean every pair gives different results. Matrix multiplication is a familiar example.','A nonzero horizontal shear and vertical shear can give AB≠BA.','noncommutative',['noncommutativity','non-commutative'],{sourceKeys:['matrix']});
  add('linear-system-solution','Linear system and its solutions','linear',['Ax=b'],'A collection of equations made from constant terms and fixed-coefficient multiples of the unknowns. A solution satisfies them all. Over the reals there may be none, one unique solution or infinitely many solutions.','r+s=2 and 2r+2s=4 have infinitely many solutions; requiring 2r+2s=5 instead gives none.','A times x equals b',['linear system','linear systems','system of linear equations'],{wordMatches:['linear system','linear equations','unique solution','infinitely many solutions','infinite solutions','no solution','solution set'],sourceKeys:['subspaces','basis'],tokens:['Ax=b']});
  add('vector-space-dimension','Dimension of a vector space','linear',['dim(V)'],'For a finite-dimensional vector space, the number of vectors in any basis. This counts independent directions, rather than the physical units of a quantity or the rows and columns of a matrix.','The real plane has dimension 2; a line through its origin has dimension 1.','dimension of V',['vector space dimension','dimension','dimensions','independent directions'],{wordMatches:['vector space dimension','dimension of a vector space','dimension of its span','dimension of the span','dimension of the space','independent directions','one-dimensional span','two-dimensional span'],sourceKeys:['basis'],tokens:['dim(V)']});
  add('affine-combination','Affine combination','linear',[],'A linear combination whose coefficients sum to 1. They may be negative. For two distinct points, all such real coefficient pairs trace the whole line through the points.','2u−v is affine because 2+(−1)=1.','affine combination',['affine combinations'],{sourceKeys:['convex']});
  add('convex-combination','Convex combination','linear',[],'A linear combination with nonnegative coefficients that sum to 1. For two points, the result stays on their joining segment, including its endpoints.','0.25u+0.75v is convex; 2u−v is not.','convex combination',['convex combinations'],{sourceKeys:['convex']});
  add('orthonormal','Orthonormal','linear',[],'A collection of unit vectors in which every pair of distinct vectors is orthogonal. If the collection also spans the space, it is an orthonormal basis. A general basis need not have either special property.','((1,0),(0,1)) is an orthonormal basis of the real plane.','orthonormal',['orthonormal basis','orthonormal vectors'],{sourceKeys:['orthonormal']});
  add('matrix-dimensions','Matrix dimensions','linear',['m×n'],'The numbers of rows and columns, written in that order as m×n. In a product, the left matrix’s column count must equal the right matrix’s row count. Size is different from rank.','A 2×3 matrix has two rows and three columns.','m by n',['matrix size','rows and columns'],{wordMatches:['matrix dimensions','matrix size','rows and columns','number of rows','number of columns','inner dimensions'],sourceKeys:['matrix']});
  // Greek character identities are separate from the mathematical roles assigned to them.
  const capitals=[
    ['alpha','Α','A',null],['beta','Β','B',null],['gamma','Γ',null,'Gamma'],
    ['epsilon','Ε','E',null],['zeta','Ζ','Z',null],['eta','Η','H',null],['theta','Θ',null,'Theta'],
    ['iota','Ι','I',null],['kappa','Κ','K',null],['lambda','Λ',null,'Lambda'],['mu','Μ','M',null],
    ['nu','Ν','N',null],['xi','Ξ',null,'Xi'],['omicron','Ο','O',null],['pi','Π',null,'Pi'],
    ['rho','Ρ','P',null],['sigma','Σ',null,'Sigma'],['tau','Τ','T',null],['upsilon','Υ','Y','Upsilon'],
    ['phi','Φ',null,'Phi'],['chi','Χ','X',null],['psi','Ψ',null,'Psi'],['omega','Ω',null,'Omega']
  ];
  for(const [name,glyph,lookalike,command] of capitals){
    const distinction=name==='sigma'?' It is a letter, distinct from the summation operator ∑.':name==='pi'?' It is a letter, distinct from the product operator ∏.':name==='omega'?' Naming a sample space Ω is one context-specific use.':lookalike?' It resembles Latin '+lookalike+' but is a different character.':'';
    const lowerId=name==='sigma'?'sigma-small':name;
    add(name+'-capital','Capital '+name,'greek',[glyph],'The Greek capital letter '+(name==='lambda'?'lambda (Unicode name: lamda)':name)+'. Its mathematical meaning must be stated in context.'+distinction,glyph+' can name a quantity after the author defines it.','capital '+name,[name,'uppercase '+name,'Greek capital '+name,...(name==='lambda'?['capital lamda','uppercase lamda']:[])],{sourceKeys:['greek'],lookupAliases:command?['\\'+command]:[],wordMatches:['capital '+name,'uppercase '+name,'Greek capital '+name],relatedIds:[lowerId]});
  }
  add('pi-variant','Variant pi','greek',['ϖ'],'The pi symbol, a variant Greek pi character. It can be used as a separately defined variable; it does not automatically have the constant value π.','ϖ and π may name different quantities in one expression.','variant pi',['varpi','pi symbol'],{sourceKeys:['greek'],lookupAliases:['\\varpi'],relatedIds:['pi']});
  add('digamma','Digamma','greek',['ϝ','Ϝ'],'An archaic Greek letter also used as a mathematical symbol. Its role is defined by the author. It is outside the modern 24-letter Greek alphabet.','ϝ is a Greek character, distinct from Latin f.','digamma',['Greek digamma'],{sourceKeys:['greek'],lookupAliases:['\\digamma'],relatedIds:['gamma']});
  add('reversed-epsilon','Reversed lunate epsilon symbol','greek',['϶'],'A character named reversed lunate epsilon symbol. It is distinct from epsilon ε and from contains-as-member ∋; its mathematical role depends on the convention being used.','϶, ε and ∋ are different Unicode characters.','reversed epsilon',['backepsilon','reversed epsilon'],{sourceKeys:['greek','symbols'],lookupAliases:['\\backepsilon'],relatedIds:['epsilon','element']});
  add('grouping-parentheses','Parentheses and grouping','notation',['(',')','( )'],'Parentheses can group an expression or hold function inputs or ordered coordinates. Read their role from the surrounding notation; parentheses do not always mean multiplication.','2(3+4)=14, while f(3) supplies input 3 to f.','parentheses',['round brackets','grouping parentheses'],{sourceKeys:['arithmetic','functions'],lookupAliases:['\\left(','\\right)'],wordMatches:['parentheses','grouping parentheses'],relatedIds:['order-of-operations','function-notation','ordered-pair']});
  add('square-brackets','Square brackets','notation',['[',']','[ ]'],'Brackets can group an expression, display a matrix, or include an interval endpoint. Their shape alone does not choose between these roles.','[0,1] is a closed interval; [[1,0],[0,1]] is a matrix layout.','square brackets',['brackets'],{sourceKeys:['domain','matrix'],lookupAliases:['\\lbrack','\\rbrack'],wordMatches:['square brackets'],relatedIds:['closed-interval','matrix','order-of-operations']});
  add('curly-braces','Braces','notation',['{','}','{ }'],'Visible braces often enclose a set or its defining condition. In TeX source, unprinted braces also group material for commands; those source groups are not additional sets.','{1,2,3} is a set with three elements.','braces',['curly braces','set braces'],{sourceKeys:['reading'],lookupAliases:['\\{','\\}','\\lbrace','\\rbrace'],wordMatches:['curly braces','set braces'],relatedIds:['set','set-builder']});
  add('vertical-bar','Vertical bar: read the context','notation',['|','∣'],'A bar has several roles: paired bars can indicate absolute value, complex modulus or a determinant; a single bar can mean given, divides, such that, or evaluation at a value. It has no single universal operation.','|−3|=3; P(A|B) reads probability of A given B.','vertical bar',['single bar','pipe'],{sourceKeys:['numbers','chance','reading','dlmfNotation'],lookupAliases:['\\vert','\\lvert','\\rvert','\\mid'],wordMatches:['vertical bar'],relatedIds:['absolute-value','complex-modulus','conditional-probability','divisibility','evaluation-bar','determinant']});
  add('prime-mark','Prime mark','notation',['′',"'",'’','″'],'A prime marks a related object or, on a function in a derivative convention, differentiation. A transformed coordinate x′ is not automatically a derivative. Double prime can similarly label an object or a second derivative.','x′=2x can label a transformed coordinate; f′(a) is derivative notation.','prime; double prime',['prime mark','apostrophe','transformed coordinate','double prime'],{sourceKeys:['dlmfNotation','derivative','coordinates'],lookupAliases:['\\prime'],wordMatches:['prime mark','transformed coordinate','double prime'],relatedIds:['derivative','higher-derivative','coordinate','linear-map']});
  add('superscript','Superscript and caret','notation',['^','⁰','¹','²','³','ⁿ','ᵏ','⁻¹'],'A superscript is raised notation. It often denotes a power, but can instead indicate an inverse, transpose or label. A caret is a common typed way to enter a superscript or power.','x^2 means x squared; f⁻¹ can mean an inverse function.','superscript; caret',['raised index','caret','superscripts'],{sourceKeys:['powers','dlmfNotation'],lookupAliases:['**'],wordMatches:['superscript','superscripts','caret'],relatedIds:['exponent','inverse-function','inverse-matrix','transpose']});
  add('ordered-pair','Ordered pair','notation',['(x,y)','(a,b)'],'Two entries in a specified first-to-second order. In coordinates, the first and second entries locate a point relative to the chosen axes or basis. Swapping them usually changes the pair.','(2,3) is different from (3,2).','x comma y',['ordered pairs','coordinate pair'],{sourceKeys:['reading','vectors'],relatedIds:['coordinate','basis','cartesian-product']});
  add('column-vector','Column vector layout','notation',['(x;y)','[x;y]'],'A coordinate list written in one column, with its entry order preserved. It can represent a vector relative to a chosen basis. In the basis card, stacked binom notation is a column layout, not a counting instruction.','The column with entries 3 then 4 represents coordinates (3,4).','column vector',['column vectors','column coordinates'],{sourceKeys:['matrix','dlmfNotation','coordinates'],lookupAliases:['\\binom','\\binom{x}{y}','\\binom{r}{s}'],mathSymbols:['\\binom'],formulaCards:['basis'],relatedIds:['coordinate-vector','matrix-dimensions','binomial-coefficient']});
  add('open-interval','Open interval','notation',['(a,b)'],'For real a<b, the numbers strictly between a and b. The endpoints are excluded. Parentheses can also denote an ordered pair, so context matters.','(0,1) means 0<x<1 when it is an interval.','open interval from a to b',['open intervals'],{sourceKeys:['domain'],relatedIds:['interval','closed-interval','ordered-pair']});
  add('closed-interval','Closed interval','notation',['[a,b]'],'For real a≤b, the numbers from a through b including both endpoints.','[0,1] includes 0, 1 and all real numbers between them.','closed interval from a to b',['closed intervals'],{sourceKeys:['domain'],relatedIds:['interval','open-interval','half-open-interval']});
  add('half-open-interval','Half-open interval','notation',['[a,b)','(a,b]'],'An interval that includes one finite endpoint and excludes the other. The square bracket includes; the parenthesis excludes. Infinity is never included as a real endpoint.','[0,1) means 0≤x<1.','half-open interval',['half closed interval','half-open intervals'],{sourceKeys:['domain'],relatedIds:['interval','open-interval','closed-interval','infinity']});
  add('scientific-notation','Scientific and e notation','notation',['a×10ⁿ','1e3','1E3'],'Write a value as a coefficient times a power of ten. For a nonzero value in normalized scientific notation, the coefficient’s absolute value lies from 1 up to but excluding 10. Display e or E introduces the power of ten; it is not Euler’s number.','1.2e−3 = 1.2×10⁻³ = 0.0012.','times ten to the power',['scientific notation','e notation','E notation','exponential display'],{sourceKeys:['powers','numeric'],lookupAliases:['1e-6','1e−6','1.2e-3','1.2e−3'],wordMatches:['scientific notation','e notation','exponential display'],relatedIds:['exponent','eulers-number','approximately-equal']});
  add('ellipses','Ellipsis and continuation marks','notation',['…','⋯','⋮','⋱','...'],'Marks that some entries or terms are omitted according to a stated pattern. Horizontal, vertical and diagonal dots indicate different layout directions. Dots alone do not prove that a pattern continues forever.','1,2,3,… continues the stated counting pattern.','and so on',['ellipsis','ellipses','continuation dots'],{sourceKeys:['reading','dlmfAlgebra'],lookupAliases:['\\ldots','\\cdots','\\vdots','\\ddots'],relatedIds:['sequence','summation','matrix']});
  add('natural-number','Natural-number notation','sets',['ℕ','ℕ₀','ℕ⁺'],'Natural numbers are whole counting numbers; authors differ about including zero in ℕ. The explicit form ℕ₀ includes zero, while ℕ⁺ usually denotes positive integers. Check the stated convention.','With zero included, ℕ₀={0,1,2,…}.','natural numbers',['natural numbers','nonnegative integers','positive integers'],{sourceKeys:['reading','dlmfNotation'],lookupAliases:['\\mathbb{N}','\\mathbb N','\\mathbb{N}_0','\\mathbb N_0','N_0'],mathSymbols:['\\mathbb{N}','\\mathbb N','ℕ'],relatedIds:['integer','sequence','subscript']});
  add('empty-set','Empty set','sets',['∅','{}'],'The set with no elements. It differs from {0}, which contains one element, and from the number zero.','∅ has zero elements; {∅} has one.','empty set',['emptyset','null set'],{sourceKeys:['reading'],lookupAliases:['\\emptyset','\\varnothing'],mathSymbols:['\\emptyset','\\varnothing','∅'],relatedIds:['set','element']});
  add('subset','Subset, allowing equality','sets',['⊆'],'Every element of the first set also belongs to the second; the sets may be equal.','{1,2}⊆{1,2,3}.','is a subset of or equal to',['subset','subsets'],{sourceKeys:['reading'],lookupAliases:['\\subseteq'],mathSymbols:['\\subseteq','⊆'],relatedIds:['proper-subset','superset','element']});
  add('superset','Superset, allowing equality','sets',['⊇'],'The first set contains every element of the second; the sets may be equal. It reverses the direction of the subset relation.','{1,2,3}⊇{1,2}.','is a superset of or equal to',['superset','supersets'],{sourceKeys:['reading'],lookupAliases:['\\supseteq'],mathSymbols:['\\supseteq','⊇'],relatedIds:['subset','proper-superset']});
  add('proper-subset','Proper subset','sets',['⊊','⊂'],'A subset that is not the whole second set. The symbol ⊊ makes strictness explicit. Some authors use ⊂ for any subset instead; follow their convention.','{1}⊊{1,2}.','is a proper subset of',['strict subset','proper subset'],{sourceKeys:['reading','symbols'],lookupAliases:['\\subset','\\subsetneq'],mathSymbols:['\\subsetneq','⊊'],relatedIds:['subset','proper-superset']});
  add('proper-superset','Proper superset','sets',['⊋','⊃'],'A set containing the second set and at least one additional element. The symbol ⊋ makes strictness explicit; ⊃ can have a different convention in some texts.','{1,2}⊋{1}.','is a proper superset of',['strict superset','proper superset'],{sourceKeys:['reading','symbols'],lookupAliases:['\\supset','\\supsetneq'],mathSymbols:['\\supsetneq','⊋'],relatedIds:['superset','proper-subset']});
  add('set-union','Union','sets',['∪','⋃'],'The set of elements belonging to at least one of the stated sets. A large union sign combines a whole indexed family of sets.','{1,2}∪{2,3}={1,2,3}.','union',['set union','union of sets'],{sourceKeys:['reading'],lookupAliases:['\\cup','\\bigcup'],mathSymbols:['\\cup','\\bigcup','∪','⋃'],relatedIds:['set-intersection','set','logical-or']});
  add('set-intersection','Intersection','sets',['∩','⋂'],'The set of elements shared by all the stated sets. A large intersection sign combines an indexed family.','{1,2}∩{2,3}={2}.','intersection',['set intersection','intersection of sets'],{sourceKeys:['reading'],lookupAliases:['\\cap','\\bigcap'],mathSymbols:['\\cap','\\bigcap','∩','⋂'],relatedIds:['set-union','set','logical-and']});
  add('set-difference','Set difference','sets',['∖','A\\B'],'The elements belonging to the first set but not the second. Reversing the set order can change the result.','{1,2}∖{2,3}={1}.','set minus',['set difference','relative complement'],{sourceKeys:['reading'],lookupAliases:['\\setminus','\\smallsetminus'],mathSymbols:['\\setminus','∖'],relatedIds:['set-complement','set-intersection']});
  add('set-complement','Set complement','sets',['Aᶜ','A^c','∁'],'The elements of a specified universe that are outside the set. A complement requires knowing the surrounding universe.','If U={1,2,3} and A={1}, then Aᶜ={2,3}.','A complement',['complement of a set','set complement'],{sourceKeys:['reading'],lookupAliases:['\\complement'],mathSymbols:['\\complement'],relatedIds:['set-difference','set','logical-not']});
  add('cartesian-product','Cartesian product','sets',['A×B'],'The set of ordered pairs whose first entry comes from A and second entry from B. Here × combines sets, rather than multiplying two numbers.','{1,2}×{a}={(1,a),(2,a)}.','A Cartesian product B',['Cartesian product','product of sets'],{sourceKeys:['reading'],lookupAliases:['\\times'],wordMatches:['Cartesian product','product of sets'],relatedIds:['ordered-pair','cartesian-power','multiplication']});
  add('cartesian-power','Cartesian power and coordinate space','sets',['Aⁿ','ℝ²','[0,1]²'],'A repeated Cartesian product. ℝ² consists of ordered pairs of real numbers; [0,1]² consists of pairs with each coordinate between 0 and 1. The superscript counts coordinate positions rather than squaring a number.','[0,1]²=[0,1]×[0,1], the filled unit square.','A to the Cartesian n; R two',['Cartesian power','real plane','unit square','coordinate space'],{sourceKeys:['reading','vectors'],lookupAliases:['\\mathbb{R}^2','\\mathbb R^2','[0,1]^2','R^2'],mathSymbols:['\\mathbb{R}^2','\\mathbb R^2','[0,1]^2','ℝ²','[0,1]²'],relatedIds:['cartesian-product','ordered-pair','square','superscript']});
  add('set-builder','Set-builder notation','sets',['{x:P(x)}','{x∣P(x)}',':'],'A description of a set by specifying allowed objects and a condition they must satisfy. A colon or vertical bar can mean such that in this setting.','{x∈ℝ:x>0} is the set of positive real numbers.','the set of x such that',['set-builder notation','such that'],{sourceKeys:['reading'],lookupAliases:['\\colon'],wordMatches:['set-builder notation','set builder'],relatedIds:['set','element','vertical-bar','logical-conditional']});
  add('logical-not','Logical negation','sets',['¬'],'Reverse a statement’s truth value: not P is true exactly when P is false. A typed ! or ~ may serve this role in particular programming or logic conventions.','If P says x>0, ¬P says x≤0 for real x.','not',['negation','logical not'],{sourceKeys:['logic','reading'],lookupAliases:['\\neg','\\lnot'],mathSymbols:['\\neg','\\lnot','¬'],wordMatches:['logical negation','logical not'],relatedIds:['logical-and','logical-or','counterexample']});
  add('logical-and','Logical conjunction','sets',['∧'],'A statement joining two claims that is true exactly when both claims are true. A wedge can have other roles, such as an exterior product, in other mathematical settings.','x>0 ∧ x<1 means both inequalities hold.','and',['conjunction','logical and'],{sourceKeys:['logic','reading'],lookupAliases:['\\land','\\wedge'],mathSymbols:['\\land','∧'],wordMatches:['logical conjunction','logical and'],relatedIds:['logical-or','set-intersection']});
  add('logical-or','Logical disjunction','sets',['∨'],'A statement true when at least one of its claims is true, including the case when both are true. This is inclusive or.','x=0 ∨ x=1 permits either listed value.','or',['disjunction','inclusive or','logical or'],{sourceKeys:['logic','reading'],lookupAliases:['\\lor','\\vee'],mathSymbols:['\\lor','∨'],wordMatches:['logical disjunction','inclusive or','logical or'],relatedIds:['exclusive-or','logical-and','set-union']});
  add('exclusive-or','Exclusive or','sets',['⊕','⊻'],'A logical operation true when exactly one of two claims is true. The symbol ⊕ also has distinct algebraic uses, so its role must be specified.','For true P and false Q, P xor Q is true.','exclusive or',['xor','exclusive disjunction'],{sourceKeys:['logic','reading'],lookupAliases:['\\oplus','\\veebar'],wordMatches:['exclusive or','exclusive disjunction','xor'],relatedIds:['logical-or','logical-not']});
  add('unique-exists','Unique existence','sets',['∃!'],'There exists exactly one object satisfying the stated condition. It adds uniqueness to ordinary existential quantification.','∃!y∈ℝ with y=2x+1 means each fixed real x determines one such y.','there exists exactly one',['unique existence','exists unique','exactly one'],{sourceKeys:['unique','reading'],lookupAliases:['\\exists!'],mathSymbols:['\\exists!','∃!'],relatedIds:['there-exists','function','linear-system-solution']});
  add('not-exists','Nonexistence quantifier','sets',['∄'],'No object in the stated domain satisfies the following condition. It is the negation of an existential claim.','∄x∈ℝ with x²=−1.','there does not exist',['nonexistence','does not exist'],{sourceKeys:['reading'],lookupAliases:['\\nexists'],mathSymbols:['\\nexists','∄'],relatedIds:['there-exists','logical-not','domain']});
  add('logical-conditional','Logical conditional arrow','sets',['P→Q'],'A statement false only when P is true and Q is false in classical logic. An arrow between sets can instead specify a function’s domain and codomain.','If P means x>2 and Q means x>0, then P→Q holds for real x.','if P then Q',['conditional statement','material implication'],{sourceKeys:['reading'],lookupAliases:['\\rightarrow','\\to'],formulaCards:[],relatedIds:['implication','function-arrow','limit-arrow']});
  add('therefore','Therefore sign','sets',['∴'],'A written cue that the following statement is presented as a conclusion of preceding reasoning. The sign itself does not supply a proof.','x=2 ∴ x²=4.','therefore',['therefore sign'],{sourceKeys:['symbols','reading'],lookupAliases:['\\therefore'],relatedIds:['proof','implication']});
  add('because','Because sign','sets',['∵'],'A written cue introducing a reason for a claim. Correctness still depends on that reason and its assumptions.','x²=4 because x=2 can be written using ∵ before the reason.','because',['because sign'],{sourceKeys:['symbols','reading'],lookupAliases:['\\because'],relatedIds:['proof','therefore']});
  add('truth-constants','Truth and falsity constants','sets',['⊤','⊥'],'In a declared logic convention, ⊤ denotes truth and ⊥ falsity. The symbol ⊥ also means perpendicular in geometry; context determines which role is intended.','P∧⊤ has the same truth value as P.','true; false',['truth constant','falsehood','falsity'],{sourceKeys:['reading','symbols'],lookupAliases:['\\top','\\bot'],formulaCards:[],relatedIds:['logical-and','logical-or','orthogonal']});
  add('defined-equal','Defined equality','notation',['≔',':=','≝'],'Introduce a definition: the expression on the designated side is being assigned its meaning by the other side. This differs from proving an equality between previously defined expressions.','f(x):=x² defines a rule.','is defined as',['defined as','definition sign'],{sourceKeys:['reading','symbols'],lookupAliases:['\\coloneqq','\\coloneq','\\triangleq'],mathSymbols:[':=','≔'],relatedIds:['equality','equation','function']});
  add('proportional','Proportionality','notation',['∝'],'One quantity is a constant multiple of the other over the setting being stated. The constant and allowed inputs still matter.','y∝x can mean y=kx for a fixed k.','is proportional to',['proportionality','directly proportional'],{sourceKeys:['functions'],lookupAliases:['\\propto'],mathSymbols:['\\propto','∝'],relatedIds:['ratio','coefficient','linear-affine']});
  add('minus-plus','Minus or plus','notation',['∓'],'The opposite sign choice paired with ±: when one expression takes the upper sign, the matching expression takes its own upper sign, and likewise for the lower signs.','a±b and a∓b pair a+b with a−b.','minus or plus',['minus plus','paired signs'],{sourceKeys:['symbols','numbers'],lookupAliases:['\\mp'],relatedIds:['plus-minus','subtraction']});
  add('function-arrow','Function domain and codomain arrow','notation',['A→B'],'The rule takes inputs from A and returns outputs in B. The arrow specifies a function’s declared direction; it is not a subtraction or a numerical limit.','f:A→B declares a function from A to B.','from A to B',['function arrow','map from','domain codomain arrow'],{sourceKeys:['reading','functions'],lookupAliases:['\\to','\\rightarrow'],mathSymbols:['\\to','\\rightarrow','→'],formulaCards:['function','function-composition','matrix-linear-map','basis','matrix-product'],relatedIds:['domain','codomain','maps-to','limit-arrow']});
  add('maps-to','Input-to-output arrow','notation',['↦'],'Describe what an individual input is sent to by a rule. This differs from A→B, which names the function’s input and output sets.','x↦x² states the rule sending x to x squared.','maps to',['maps-to arrow','sent to'],{sourceKeys:['reading','functions'],lookupAliases:['\\mapsto'],mathSymbols:['\\mapsto','↦'],relatedIds:['function-notation','function-arrow']});
  add('limit-arrow','Approach arrow','notation',['x→a'],'In limit notation, the input moves arbitrarily close to a specified value. It does not require the function to be defined at that value.','lim as x→0 of x² equals 0.','x approaches a',['approaches','approach arrow'],{sourceKeys:['limits'],lookupAliases:['\\to','\\rightarrow'],mathSymbols:['\\to','\\rightarrow'],formulaCards:['limit','derivative'],relatedIds:['limit','one-sided-limit','function-arrow']});
  add('type-annotation','Colon in a declaration','notation',['f:A→B',':'],'A colon can introduce the kind or signature of an object. In f:A→B it declares the function’s input and output sets; it does not mean division or set-builder such that in that use.','f:ℝ→ℝ declares a real-input, real-output function.','f is a function from A to B',['type annotation','function signature','declaration colon'],{sourceKeys:['reading','functions'],relatedIds:['function-arrow','set-builder','ratio']});
  add('factorial','Factorial','discrete',['n!','!'],'For a nonnegative integer n, multiply the positive integers from 1 through n; the empty case is defined by 0!=1. The postfix exclamation mark has this meaning in counting formulas.','4!=4×3×2×1=24.','n factorial',['factorials'],{sourceKeys:['dlmfAlgebra','numeric'],lookupAliases:['factorial(n)'],mathSymbols:['factorial('],relatedIds:['binomial-coefficient','product-notation','natural-number']});
  add('binomial-coefficient','Binomial coefficient','discrete',['C(n,k)','C(6,k)','nCk'],'For integers 0≤k≤n, the number of k-element selections from n distinct objects, ignoring selection order. It equals n!/[k!(n−k)!]. A similar stacked layout can represent a column vector in a different context.','C(6,2)=15.','n choose k',['choose','binomial coefficient','combinations count'],{sourceKeys:['dlmfAlgebra','binomial'],lookupAliases:['\\binom','\\binom{n}{k}','\\binom{6}{k}','C(6,2)'],mathSymbols:['\\binom','C(6,','C(n,'],formulaCards:['probability'],relatedIds:['factorial','probability','column-vector']});
  add('product-notation','Indexed product','discrete',['∏'],'Multiply terms over the stated index range. The index and bounds specify which factors occur. It is distinct from the Greek letter Π.','∏ from k=1 to 3 of k equals 1×2×3=6.','product',['product notation','indexed product'],{sourceKeys:['dlmfAlgebra','symbols'],lookupAliases:['\\prod'],mathSymbols:['\\prod','∏'],relatedIds:['summation','factorial','pi-capital']});
  add('sequence','Sequence notation','discrete',['aₙ','(aₙ)'],'An ordered list indexed over a stated domain, often integers. The subscript identifies the position; it does not mean multiply by the index. A sequence may be finite or infinite.','For aₙ=2n and n≥0, the first values are 0,2,4,….','a sub n',['sequences','sequence notation'],{sourceKeys:['reading','series'],relatedIds:['subscript','natural-number','iteration','infinite-series']});
  add('infinite-series','Infinite series notation','discrete',['∑ₙ₌₀∞aₙ'],'An infinite sum is defined through the limit of its finite partial sums, when that limit exists. Writing a summation sign with an infinite bound does not guarantee a finite value.','1+1/2+1/4+… has sum 2.','sum of a sub n over all stated indices',['infinite series','partial sums'],{sourceKeys:['series'],relatedIds:['summation','sequence','limit','infinity']});
  add('divisibility','Divisibility','discrete',['a∣b','a|b'],'For integers, a divides b when b=ak for some integer k. The single bar here is a relation, not absolute value, division or conditional probability.','3∣12 because 12=3×4.','a divides b',['divides','divisibility'],{sourceKeys:['reading'],lookupAliases:['\\mid'],formulaCards:[],relatedIds:['integer','division','modulo','vertical-bar']});
  add('modulo','Modulo and integer remainder','discrete',['a mod m','mod'],'For positive integer m, a mod m is the unique remainder r with 0≤r<m and a=qm+r for an integer q. Programming remainder operators can use different conventions for negative inputs.','17 mod 5 = 2.','a modulo m',['modular arithmetic','modulo','remainder'],{sourceKeys:['reading'],lookupAliases:['\\bmod','\\pmod','mod(a,m)'],wordMatches:['modulo','modular arithmetic','integer remainder'],relatedIds:['division','integer','modular-congruence']});
  add('modular-congruence','Congruence modulo an integer','discrete',['a≡b (mod m)'],'For a positive integer m, the difference a−b is divisible by m. The same ≡ glyph can instead mark an identity in another context.','17≡2 (mod 5).','a is congruent to b modulo m',['congruence modulo','modular congruence'],{sourceKeys:['reading'],lookupAliases:['\\equiv','\\pmod'],formulaCards:[],relatedIds:['modulo','divisibility','identity']});
  add('exponential-function','Natural exponential notation','functions',['exp(x)','eˣ'],'exp(x) means e raised to x. This function notation is distinct from an e in a numeric display such as 1e3, which introduces a power of ten.','exp(0)=1 and exp(1)=e.','exponential of x',['exp','natural exponential'],{sourceKeys:['exp'],lookupAliases:['\\exp','exp'],mathSymbols:['\\exp','exp('],relatedIds:['exponential','eulers-number','scientific-notation']});
  add('minimum','Minimum','functions',['min','min(a,b)'],'The smallest value in a stated collection, when it exists. This returns a value; argmin instead identifies inputs where a function attains its minimum. The abbreviation min can also mean a minute when used as a unit.','min(3,−2,5)=−2.','minimum',['minimum','minimum value'],{sourceKeys:['builtin','fundamental'],lookupAliases:['\\min','min(...)'],mathSymbols:['\\min','min('],wordMatches:['minimum','minimum value'],relatedIds:['maximum','argmin','measurement-unit-symbols']});
  add('maximum','Maximum','functions',['max','max(a,b)'],'The largest value in a stated collection, when it exists. A function need not attain a largest value on every domain.','max(3,−2,5)=5.','maximum',['maximum','maximum value'],{sourceKeys:['builtin','fundamental'],lookupAliases:['\\max','max(...)'],mathSymbols:['\\max','max('],wordMatches:['maximum','maximum value'],relatedIds:['minimum','argmax','domain']});
  add('argmin','Minimizing input: argmin','functions',['argmin'],'The input or set of inputs attaining a function’s smallest value on the declared domain. It differs from that smallest output value. There may be no attaining input or more than one.','For f(x)=x² over ℝ, the minimizing input is 0.','arg min',['arg min','minimizer','minimizing input'],{sourceKeys:['convex'],lookupAliases:['\\argmin','\\operatorname{argmin}'],wordMatches:['argmin','minimizer','minimizing input'],relatedIds:['minimum','domain','function']});
  add('argmax','Maximizing input: argmax','functions',['argmax'],'The input or set of inputs attaining a function’s largest value on the declared domain. It differs from the largest output value and may be absent or nonunique.','For f(x)=−x² over ℝ, the maximizing input is 0.','arg max',['arg max','maximizer','maximizing input'],{sourceKeys:['convex'],lookupAliases:['\\argmax','\\operatorname{argmax}'],wordMatches:['argmax','maximizer','maximizing input'],relatedIds:['maximum','domain','function']});
  add('floor','Floor function','functions',['⌊x⌋','⌊','⌋'],'The greatest integer less than or equal to a real input. Rounding down moves toward negative infinity, including for negative inputs.','⌊2.7⌋=2 and ⌊−2.7⌋=−3.','floor of x',['floor','round down'],{sourceKeys:['numeric'],lookupAliases:['\\lfloor','\\rfloor','floor(x)'],mathSymbols:['\\lfloor','floor('],relatedIds:['ceiling','integer','fractional-part']});
  add('ceiling','Ceiling function','functions',['⌈x⌉','⌈','⌉'],'The least integer greater than or equal to a real input. Rounding up moves toward positive infinity.','⌈2.2⌉=3 and ⌈−2.2⌉=−2.','ceiling of x',['ceiling','ceil','round up'],{sourceKeys:['numeric'],lookupAliases:['\\lceil','\\rceil','ceil(x)'],mathSymbols:['\\lceil','ceil('],relatedIds:['floor','integer']});
  add('fractional-part','Fractional-part function','functions',['frac(x)','frac(d)'],'In these cards, frac(x)=x−floor(x), a value in [0,1). This wraps a real coordinate into one repeating unit. It differs from the TeX command \\frac, which typesets division.','frac(2.7)=0.7 and frac(−0.2)=0.8.','fractional part of x',['fractional part','fractional-part','frac'],{sourceKeys:['numeric'],lookupAliases:['frac','fract','fract(x)'],mathSymbols:['frac(','fract(','\\operatorname{frac}'],wordMatches:['fractional part','fractional-part'],relatedIds:['floor','half-open-interval','fraction']});
  add('sign-function','Sign function','functions',['sgn(x)','sign(x)'],'Return −1 for a negative real number, 0 for zero, and 1 for a positive number. This reports the sign rather than the number’s magnitude.','sgn(−5)=−1, sgn(0)=0, sgn(5)=1.','sign of x',['signum','sgn','sign function'],{sourceKeys:['numbers'],lookupAliases:['sign','sgn','\\operatorname{sgn}'],mathSymbols:['sign(','sgn(','\\operatorname{sgn}'],relatedIds:['sign','absolute-value','orientation']});
  add('tangent-function','Tangent function','functions',['tan'],'For angles where cosine is nonzero, tan(θ)=sin(θ)/cos(θ). This trigonometric function differs from a tangent line to a curve.','tan(π/4)=1.','tangent',['tan','trigonometric tangent'],{sourceKeys:['trigSix'],lookupAliases:['\\tan','tan(x)'],mathSymbols:['\\tan','tan('],wordMatches:['tangent function','trigonometric tangent'],relatedIds:['sine','cosine','tangent','arctangent']});
  add('secant-function','Secant function','functions',['sec'],'The reciprocal of cosine where cosine is nonzero. This function differs from a secant line through two curve points.','sec(0)=1/cos(0)=1.','secant',['sec','trigonometric secant'],{sourceKeys:['trigSix'],lookupAliases:['\\sec'],mathSymbols:['\\sec'],wordMatches:['secant function','trigonometric secant'],relatedIds:['cosine','reciprocal','secant']});
  add('cosecant-function','Cosecant function','functions',['csc'],'The reciprocal of sine where sine is nonzero.','csc(π/2)=1.','cosecant',['csc','cosecant'],{sourceKeys:['trigSix'],lookupAliases:['\\csc'],mathSymbols:['\\csc'],relatedIds:['sine','reciprocal']});
  add('cotangent-function','Cotangent function','functions',['cot'],'The ratio cos(θ)/sin(θ) where sine is nonzero.','cot(π/4)=1.','cotangent',['cot','cotangent'],{sourceKeys:['trigSix'],lookupAliases:['\\cot'],mathSymbols:['\\cot'],relatedIds:['sine','cosine','tangent-function']});
  add('arcsine','Inverse sine','functions',['arcsin','sin⁻¹'],'The angle in [−π/2,π/2] whose sine is the given real input in [−1,1]. In this convention sin⁻¹ is inverse sine, not the reciprocal of sine.','arcsin(1)=π/2.','arc sine',['arcsin','inverse sine'],{sourceKeys:['inverseTrig'],lookupAliases:['\\arcsin','asin','asin(x)'],mathSymbols:['\\arcsin','asin('],relatedIds:['sine','inverse-function','cosecant-function']});
  add('arccosine','Inverse cosine','functions',['arccos','cos⁻¹'],'The angle in [0,π] whose cosine is the given real input in [−1,1]. This principal range makes the inverse single-valued.','arccos(−1)=π.','arc cosine',['arccos','inverse cosine'],{sourceKeys:['inverseTrig'],lookupAliases:['\\arccos','acos','acos(x)'],mathSymbols:['\\arccos','acos('],relatedIds:['cosine','inverse-function']});
  add('arctangent','Inverse tangent','functions',['arctan','tan⁻¹'],'The angle in (−π/2,π/2) whose tangent is the given real input. A ratio alone loses the full quadrant information provided by atan2.','arctan(1)=π/4.','arc tangent',['arctan','inverse tangent'],{sourceKeys:['inverseTrig'],lookupAliases:['\\arctan','atan','atan(x)'],mathSymbols:['\\arctan','atan('],relatedIds:['tangent-function','atan2','inverse-function']});
  add('atan2','Two-coordinate angle: atan2','functions',['atan2(y,x)'],'Find the direction angle of a nonzero vector (x,y) using both coordinate signs to choose the quadrant. The usual call order is y then x. A zero vector has no geometric direction, even if a software function returns a number.','atan2(1,0)=π/2 radians.','a tan two of y comma x',['atan2','two-argument arctangent'],{sourceKeys:['numeric'],lookupAliases:['atan2'],mathSymbols:['atan2('],relatedIds:['arctangent','complex-argument','radian','coordinate']});
  add('hypot','Euclidean length: hypot','functions',['hypot(x,y)'],'Compute √(x²+y²), the Euclidean length of a two-component vector. The name also occurs in software functions generalized to more components.','hypot(3,4)=5.','hypotenuse of x and y',['hypot','Euclidean length function'],{sourceKeys:['numeric','vectors'],lookupAliases:['hypot'],mathSymbols:['hypot('],relatedIds:['hypotenuse','magnitude','square-root']});
  add('differential','Differential notation','calculus',['dx','dt','dy'],'In an integral, dx or dt names the integration variable. In dy=f′(x)dx, dy is the linear response assigned to an increment dx; it need not equal the finite change in the function.','∫t dt integrates with respect to t.','d x; d t',['differential','differentials','with respect to'],{sourceKeys:['integral','derivative'],lookupAliases:['\\mathrm{d}x','\\mathrm{d}t'],mathSymbols:['dx','dt'],formulaCards:['integral-accumulation','signed-accumulation'],wordMatches:['differential notation','differentials'],relatedIds:['integral','derivative','increment']});
  add('higher-derivative','Higher derivative notation','calculus',['f″(x)','d²y/dx²','dⁿy/dxⁿ'],'Differentiate repeatedly, when the required derivatives exist. A second derivative differentiates the first derivative; the raised 2 in d²y/dx² records derivative order, not the square of dy/dx.','For f(x)=x³, f″(x)=6x.','second derivative; nth derivative',['second derivative','higher derivatives','double derivative'],{sourceKeys:['derivative','dlmfNotation'],lookupAliases:["f''(x)",'d^2y/dx^2'],relatedIds:['derivative','prime-mark','superscript']});
  add('indefinite-integral','Indefinite integral','calculus',['∫f(x)dx'],'A family of antiderivatives on an interval: functions whose derivative is f. The added constant records the family; this differs from a definite integral with numerical bounds.','∫2x dx=x²+C on a real interval.','indefinite integral of f with respect to x',['antiderivative','indefinite integrals'],{sourceKeys:['fundamental'],relatedIds:['integral','derivative','constant','differential']});
  add('multiple-integral','Multiple integral','calculus',['∬','∭'],'Integration over a region involving several variables. A double integral can accumulate values across a plane region; a triple integral does so across a solid region. The region and measure determine the meaning.','∬ over a unit square of 1 dA equals 1.','double integral; triple integral',['double integral','triple integral','multiple integrals'],{sourceKeys:['multiIntegral'],lookupAliases:['\\iint','\\iiint'],mathSymbols:['\\iint','\\iiint','∬','∭'],relatedIds:['integral','cartesian-power','differential']});
  add('contour-integral','Closed-path integral','calculus',['∮'],'An integral around a closed curve. The integrand, type of line integral and chosen orientation matter; the small circle does not mean the result is zero.','∮ around C indicates that C is closed.','integral around a closed curve',['contour integral','closed line integral','closed-path integral'],{sourceKeys:['lineIntegral'],lookupAliases:['\\oint'],mathSymbols:['\\oint','∮'],relatedIds:['integral','orientation','complex-number']});
  add('evaluation-bar','Evaluation at bounds','calculus',['F(x)|ₐᵇ','[F(x)]ₐᵇ'],'Evaluate the expression at the upper bound and subtract its value at the lower bound. A bar with a single specified value can instead mean substitution at that value. It is not absolute value.','[x²]₀²=2²−0²=4.','evaluated from a to b',['evaluate at bounds','evaluation bar'],{sourceKeys:['fundamental'],relatedIds:['integral','subtraction','vertical-bar']});
  add('nabla-operator','Nabla or del operator','calculus',['∇'],'A differential operator assembled from coordinate partial derivatives. Applied to a scalar function it gives a gradient; combined with a dot or cross and a vector field it gives different operations. It is not a Greek letter.','∇f is a gradient; ∇·F is a divergence.','nabla; del',['del operator','nabla operator'],{sourceKeys:['vectorCalculus','symbols'],lookupAliases:['\\nabla'],wordMatches:['nabla operator','del operator'],relatedIds:['gradient','divergence','curl','partial-derivative']});
  add('divergence','Divergence notation','calculus',['∇·F','div F'],'For a differentiable vector field in Cartesian coordinates, add each component’s partial derivative with respect to its matching coordinate. The output is a scalar function describing local net outflow.','For F=(x,y,z), div F=3.','divergence of F',['divergence','div'],{sourceKeys:['vectorCalculus'],lookupAliases:['\\operatorname{div}'],wordMatches:['divergence','divergence of'],relatedIds:['nabla-operator','partial-derivative','scalar']});
  add('curl','Curl notation','calculus',['∇×F','curl F'],'A derivative operation on a three-dimensional vector field that describes local circulation and its oriented axis. Its output is a vector; it is different from multiplying two ordinary vectors.','For F=(−y,x,0), curl F=(0,0,2).','curl of F',['curl','rotation of a field'],{sourceKeys:['vectorCalculus'],lookupAliases:['\\operatorname{curl}'],relatedIds:['nabla-operator','cross-product','orientation']});
  add('laplacian','Laplacian notation','calculus',['∇²f','Δf'],'For a sufficiently differentiable scalar function in Cartesian coordinates, add its second partial derivatives in the coordinate directions. Here Δf is an operator use of delta, distinct from a finite change in f.','For f(x,y)=x²+y², ∇²f=4.','Laplacian of f',['Laplacian','Laplace operator'],{sourceKeys:['vectorCalculus'],relatedIds:['nabla-operator','higher-derivative','delta-capital']});
  add('kronecker-delta','Kronecker delta','linear',['δᵢⱼ','δ_{ij}'],'A two-index symbol equal to 1 when the indices are equal and 0 when they differ. It can describe identity-matrix entries; it is different from a small perturbation δ or a Dirac delta.','δ₁₁=1 and δ₁₂=0.','delta i j',['Kronecker delta'],{sourceKeys:['dlmfAlgebra'],lookupAliases:['\\delta_{ij}'],relatedIds:['identity-matrix','subscript','delta-small']});
  add('complex-modulus','Complex modulus','linear',['|z|','|w|','|zw|'],'The nonnegative distance of a complex number from the origin. For z=a+bi, its modulus is √(a²+b²). The bars here differ from conditional probability, divisibility or determinant notation.','|3+4i|=5.','modulus of z',['modulus','complex absolute value','complex magnitude','moduli'],{sourceKeys:['complexPolar'],mathSymbols:['|z|','|w|','|zw|'],formulaCards:['complex-multiplication'],wordMatches:['complex modulus','complex magnitude','complex absolute value','modulus of a complex number','moduli multiply'],relatedIds:['absolute-value','complex-number','magnitude','complex-argument']});
  add('complex-argument','Argument of a complex number','linear',['arg(z)','arg(w)'],'An angle locating a nonzero complex number’s direction, determined up to full turns. A principal argument selects an interval by convention. Zero has no direction angle. This differs from a function’s input argument.','arg(i)=π/2 in the usual principal convention.','argument of z',['complex argument','argument of a complex number','arg','phase angle'],{sourceKeys:['complexPolar'],lookupAliases:['\\arg','arg(0)'],mathSymbols:['\\arg','arg('],formulaCards:['complex-multiplication'],wordMatches:['complex argument','argument of a complex number','argument of w','argument of z','arg(0)'],relatedIds:['complex-number','atan2','input','phase']});
  add('transpose','Matrix transpose','linear',['Aᵀ','A^T'],'Swap a matrix’s row and column positions. The (i,j) entry becomes the (j,i) entry. For real vectors, a transpose changes column layout into row layout without taking a reciprocal.','[[1,2],[3,4]]ᵀ=[[1,3],[2,4]].','A transpose',['transpose','transposed'],{sourceKeys:['dlmfNotation','dlmfAlgebra'],lookupAliases:['A^{T}','A^\\mathsf{T}','A^\\top'],relatedIds:['matrix','column-vector','matrix-dimensions','conjugate-transpose']});
  add('complex-conjugate','Complex conjugate','linear',['z̅','z*'],'For a+bi, replace b by −b. A bar or star can denote this operation when the context declares it. A bar over other quantities can have other meanings.','The conjugate of 2+3i is 2−3i.','z conjugate',['complex conjugate','conjugation'],{sourceKeys:['complex','dlmfNotation'],lookupAliases:['\\bar{z}','\\overline{z}','conj(z)'],relatedIds:['complex-number','imaginary-part','conjugate-transpose']});
  add('conjugate-transpose','Conjugate transpose','linear',['Aᴴ','A†','A*'],'Transpose a complex matrix and conjugate each entry. Common notations include Aᴴ, A† and A*; a star can have another declared meaning elsewhere. For real entries this equals ordinary transpose.','For a one-entry matrix [i], its conjugate transpose is [−i].','A conjugate transpose; A adjoint',['Hermitian transpose','Hermitian conjugate','matrix adjoint'],{sourceKeys:['dlmfNotation'],lookupAliases:['A^H','A^*','A^\\dagger'],relatedIds:['transpose','complex-conjugate','matrix']});
  add('cross-product','Cross product','linear',['u×v'],'In real three-dimensional Euclidean space, a vector perpendicular to both inputs, with direction fixed by the right-hand rule. Its magnitude is ‖u‖‖v‖sin(θ); parallel inputs give zero. This differs from scalar multiplication and Cartesian product.','(1,0,0)×(0,1,0)=(0,0,1).','u cross v',['cross product','vector product'],{sourceKeys:['cross'],lookupAliases:['\\times'],formulaCards:[],relatedIds:['orthogonal','orientation','dot-product','cartesian-product']});
  add('outer-product','Outer product','linear',['uvᵀ'],'For column vectors u and v, form the matrix whose (i,j) entry is uᵢvⱼ. The result is a matrix, unlike a dot product’s scalar.','For u=(1,2), v=(3,4), uvᵀ=[[3,4],[6,8]].','u outer v',['outer product','dyadic product'],{sourceKeys:['dlmfAlgebra'],lookupAliases:['uv^T','u v^T'],relatedIds:['column-vector','transpose','matrix-product','dot-product']});
  add('matrix-trace','Trace of a matrix','linear',['tr(A)'],'For a square matrix, add its main diagonal entries. Trace differs from determinant and from the entire set of matrix entries.','tr([[1,2],[3,4]])=1+4=5.','trace of A',['trace','matrix trace'],{sourceKeys:['dlmfAlgebra'],lookupAliases:['\\operatorname{tr}','tr'],wordMatches:['matrix trace','trace of a matrix','trace of A'],relatedIds:['matrix','summation','determinant']});
  add('kernel','Kernel or null space','linear',['ker(T)','ker(A)'],'The inputs a linear map sends to the zero vector. It is a subspace of the input space, rather than the set of all outputs.','For T(x,y)=(x,0), the kernel is {(0,y):y∈ℝ}.','kernel of T',['kernel','null space','nullspace'],{sourceKeys:['subspaces'],lookupAliases:['\\ker','null(A)'],wordMatches:['kernel','null space','nullspace'],relatedIds:['linear-map','subspace','image-of-map','rank']});
  add('image-of-map','Image of a map','linear',['im(T)','Im(T)'],'The outputs actually attained by a map. For a linear map it is a subspace of its codomain. This mathematical image is different from a picture file.','For T(x,y)=(x,0), the image is the horizontal axis.','image of T',['image space','range of a linear map'],{sourceKeys:['subspaces','domain'],lookupAliases:['\\operatorname{im}'],wordMatches:['image of a map','image of a function','image of the map','image space','range of a linear map'],relatedIds:['range','codomain','kernel','rank']});
  add('scalar-projection','Scalar projection','linear',['comp_u(v)'],'For nonzero u, the signed scalar (v·u)/‖u‖. It measures the component of v in u’s oriented direction. Vector projection instead returns a vector; neither formula divides safely by a zero direction.','The scalar projection of (3,4) onto (1,0) is 3.','scalar component of v along u',['signed scalar projection','scalar component'],{sourceKeys:['dot'],lookupAliases:['\\operatorname{comp}_u(v)'],mathSymbols:['comp_','\\operatorname{comp}'],formulaCards:['inner-product'],relatedIds:['projection','dot-product','magnitude','scalar']});
  add('distribution-notation','Distribution notation','chance',['X∼D','X~D','∼'],'A random variable has the stated probability distribution. The tilde here means distributed as, not geometric similarity or approximate equality. The distribution’s parameters and assumptions must be specified.','X∼Binomial(6,p) describes a count of successes in six binomial trials.','X is distributed as D',['distributed as','distribution notation','Binomial distribution'],{sourceKeys:['binomial'],lookupAliases:['\\sim','X~Binomial(n,p)'],mathSymbols:['\\sim'],formulaCards:['probability'],wordMatches:['distributed as','binomial distribution','distribution notation'],relatedIds:['random-variable','probability','binomial-coefficient','similarity']});
  add('standard-deviation','Standard deviation','chance',['SD(X)','sd(X)','σ_X'],'The nonnegative square root of variance, measuring spread in the variable’s original units. A sigma letter can have other meanings when a different role is defined.','If Var(X)=9, then SD(X)=3.','standard deviation of X',['standard deviation'],{sourceKeys:['expectation'],lookupAliases:['SD','sd'],wordMatches:['standard deviation'],relatedIds:['variance','expected-value','sigma-small']});
  add('similarity','Geometric similarity','geometry',['△ABC∼△DEF'],'Shapes with corresponding angles equal and corresponding lengths in one common scale ratio. A tilde used between shapes can denote this relation; a tilde on a random variable can instead describe a distribution.','Two squares of side lengths 1 and 3 are similar.','is similar to',['similar figures','geometric similarity','similarity'],{sourceKeys:['trigSix'],lookupAliases:['\\sim'],formulaCards:[],wordMatches:['geometric similarity','similar figures'],relatedIds:['ratio','angle','distribution-notation']});
  add('geometric-congruence','Geometric congruence','geometry',['≅','△ABC≅△DEF'],'Figures have the same shape and size: one can be moved to the other by a distance-preserving rigid motion. In algebra, a similar sign can describe an isomorphism instead.','Two squares with the same side length are congruent.','is congruent to',['congruent figures','geometric congruence'],{sourceKeys:['trigSix','symbols'],lookupAliases:['\\cong'],formulaCards:[],wordMatches:['geometric congruence','congruent figures'],relatedIds:['similarity','length','angle']});
  add('parallel','Parallel relation','geometry',['∥'],'In Euclidean plane geometry, distinct parallel lines lie in the same plane and never meet. The relation symbol can look like norm bars, which have a different role.','The lines y=1 and y=3 are parallel.','is parallel to',['parallel lines','parallel relation'],{sourceKeys:['vectors','symbols'],lookupAliases:['\\parallel'],mathSymbols:['\\parallel'],wordMatches:['parallel lines','parallel relation'],relatedIds:['orthogonal','magnitude','vertical-bar']});
  add('measurement-unit-symbols','Measurement unit symbols','units',['m','cm','mm','g','kg','L','s','min','h'],'Unit symbols name measurement standards: m metre, cm centimetre, mm millimetre, g gram, kg kilogram, L litre, s second, min minute, and h hour. The same letters can be variables or function names elsewhere.','5 cm is a length; 5 min is a duration, while min(2,5) is a minimum.','metre; centimetre; gram; litre; second; minute',['measurement units','metre','meter','centimetre','centimeter','gram','kilogram','litre','liter','second','minute','hour'],{sourceKeys:['si'],notationKinds:['unit'],wordMatches:[],lookupAliases:['m horizontally','m vertically'],relatedIds:['units','minimum','variable','powered-unit','compound-unit']});
  add('powered-unit','Squared and cubed units','units',['m²','cm²','mm²','m³','cm³'],'A unit power multiplies the unit by itself. Square units measure area and cubic units measure volume. Converting a length factor also raises that factor to the stated power.','1 m²=(100 cm)²=10,000 cm².','square metre; cubic metre',['square units','cubic units','square metre','square meter'],{sourceKeys:['si'],notationKinds:['unit'],wordMatches:[],lookupAliases:['m^2','cm^2','m^3','cm^3','m2','m3'],relatedIds:['measurement-unit-symbols','exponent','area','cartesian-power']});
  add('compound-unit','Compound units and rates','units',['m/s','m/s²','m/s^2','L/min','m·s⁻¹','m·s⁻²'],'Units can multiply, divide and carry powers. m/s is metres per second, L/min litres per minute, and m/s² metres per second squared. The last describes a rate of change of velocity, not the square of a velocity.','At 2 L/min for 3 min, the accumulated volume is 6 L.','metres per second; litres per minute',['compound units','rate units','metres per second','litres per minute'],{sourceKeys:['si'],notationKinds:['unit'],wordMatches:[],relatedIds:['measurement-unit-symbols','division','rate','powered-unit']});
  add('pixel-unit','Pixel unit: px','units',['px'],'A display-length unit. In CSS, px denotes a reference pixel, which need not equal one hardware pixel. A screen-space px value does not by itself state a physical length in metres.','A 100 px segment specifies display length.','pixels',['pixel','pixels','reference pixel'],{sourceKeys:['pixel'],notationKinds:['unit'],wordMatches:[],relatedIds:['units','measurement-unit-symbols','length']});
  add('declared-unit','Declared model units','units',[],'A story or model can state its own quantity label instead of an SI unit. Read that label with the model’s definition. Expected seedlings is an expected count, not a claim that one observed seedling is fractional.','Signal units and reference areas take their meaning from the stated model.','declared model units',['model units','abstract units','signal units','reference areas','expected seedlings','dimensionless model units','arbitrary units'],{sourceKeys:['si','expectation'],notationKinds:['unit'],wordMatches:[],relatedIds:['units','dimensionless','expected-value']});
  add('local-garden-length','Garden length label: ℓ','notation',['ℓ'],'In the garden example, this looped letter labels a side length. It is a locally defined quantity, not a universal constant or the digit 1.','ℓ=5 m can label a side five metres long.','ell',['garden length','looped ell'],{sourceKeys:['vectors','arithmetic'],lookupAliases:['\\ell'],mathSymbols:['ℓ','\\ell'],formulaCards:['quadratic-optimization'],grammarCards:['quadratic-optimization'],tokens:['ℓ'],wordMatches:[],relatedIds:['length','perimeter','variable']});
  add('local-terminal-time','Terminal time label: T','notation',['T'],'In these accumulation stories, T is the chosen ending time of an interval. A different card can assign T another role, such as naming a transformation.','An integral from 0 to T accumulates across the selected duration.','capital T, ending time',['terminal time','ending time label'],{sourceKeys:['integral'],mathSymbols:['T'],formulaCards:['integral-accumulation','signed-accumulation'],grammarCards:['integral-accumulation','signed-accumulation'],tokens:['T'],wordMatches:[],relatedIds:['integral','interval','variable']});
  add('local-complex-operand','Complex operand label: w','notation',['w'],'In the complex multiplication story, w names the complex multiplier. Its modulus gives a scale factor and its argument gives an angle when w is nonzero. It is not a universal value for w.','Choosing w=i rotates a complex input by a quarter turn.','w, the complex multiplier',['complex multiplier w'],{sourceKeys:['complexPolar'],mathSymbols:['w'],formulaCards:['complex-multiplication'],grammarCards:['complex-multiplication'],tokens:['w'],wordMatches:[],relatedIds:['complex-number','complex-modulus','complex-argument']});
  add('local-binomial-count','Success-count label: K','notation',['K'],'In the binomial story, K is the random count of successes in n trials. Its possible values are the integers from 0 through n. The letter is a local choice, not a universal meaning for K.','K=2 means two successes occurred in that trial batch.','capital K, success count',['binomial success count K'],{sourceKeys:['binomial'],mathSymbols:['K'],formulaCards:['probability'],grammarCards:['probability'],tokens:['K'],wordMatches:[],relatedIds:['random-variable','binomial-coefficient','distribution-notation']});
  add('evaluation-arrow','Calculation-flow arrow','notation',['→'],'In these worked views, an arrow can show a value passing through an operation or one displayed calculation stage leading to the next. It is a reading cue; other contexts use the same arrow for functions, implications or limits.','3 → multiply by 2 → 6 describes the value’s flow.','then; gives; flows to',['calculation arrow','evaluation arrow','gives arrow'],{sourceKeys:['functions','arithmetic'],lookupAliases:['\\rightarrow','\\to'],wordMatches:['calculation-flow arrow','evaluation arrow'],relatedIds:['function-arrow','limit-arrow','logical-conditional','expression']});
  add('local-combination-result','Combination result label: w','notation',['w'],'In the linear-combination module, w=ru+sv is the resulting vector. Its horizontal and vertical components come from the two component sums. Another card can use w for a different object.','For u=(1,0), v=(0,1), r=2 and s=3, w=(2,3).','w, the combined vector',['combined vector w'],{sourceKeys:['vectors','subspaces'],mathSymbols:['w'],formulaCards:['linear-combination'],grammarCards:['linear-combination'],tokens:['w'],wordMatches:[],relatedIds:['linear-combination','vector','component']});
  add('graph-node-label','Graph vertex labels','notation',['S','A','B','C','T'],'In the route graph, these letters name vertices. A label identifies a location; it is not itself a matrix, a time value, a measured unit or an arithmetic quantity. S and T identify the story’s start and target.','An edge A–C connects the two vertices bearing those labels.','vertex S; vertex A; vertex B; vertex C; vertex T',['graph node labels','vertex labels'],{sourceKeys:['reading'],mathSymbols:[],formulaCards:['graph-theory'],grammarCards:['graph-theory'],tokens:['S','A','B','C','T'],wordMatches:[],relatedIds:['variable','set']});
  add('binomial-distribution','Binomial distribution','chance',['Binomial(n,p)','Bin(n,p)'],'The probability distribution of the number of successes in n independent trials, each with the same success probability p. Its support is 0 through n; a varying probability or dependent trials can require another model.','If X∼Binomial(6,p), P(X=k)=C(6,k)pᵏ(1−p)⁶⁻ᵏ.','binomial distribution with n trials and probability p',['binomial distribution','Binomial'],{sourceKeys:['binomial'],lookupAliases:['\\operatorname{Binomial}','\\mathrm{Binomial}'],mathSymbols:['\\operatorname{Binomial}','\\mathrm{Binomial}','Binomial('],formulaCards:['probability'],relatedIds:['distribution-notation','binomial-coefficient','independence','random-variable']});
  add('right-arrow','Right arrow: read the context','notation',['→'],'A right-pointing arrow can mark a map’s direction, input-to-output flow, a logical conditional, or approach in a limit. The surrounding mathematical statement chooses the role; the glyph alone has no single operation.','f:A→B and x→a use the same arrow for different purposes.','right arrow',['right arrow','rightarrow'],{sourceKeys:['reading','limits','functions'],lookupAliases:['\\to','\\rightarrow'],mathSymbols:['→','\\to','\\rightarrow'],relatedIds:['function-arrow','limit-arrow','evaluation-arrow','logical-conditional']});
  add('contains-as-member','Contains as a member','sets',['∋','∌'],'A∋x means x belongs to A, with the set written first. A∌x means x does not belong to A. These relation symbols differ from Greek epsilon and from the reversed epsilon character ϶.','{1,2}∋2 means the set contains 2.','contains as a member; does not contain as a member',['contains as member','reverse membership'],{sourceKeys:['reading','symbols'],lookupAliases:['\\ni','\\owns','\\notni'],mathSymbols:['\\ni','\\owns','∋','∌'],relatedIds:['element','set','reversed-epsilon']});
  add('local-garden-width','Garden width label: w','notation',['w'],'In the garden example, w labels the chosen width. Its physical units and allowed range come from that story. Other modules can use w for a vector or a complex number.','A side w=3 m is three metres wide.','w, garden width',['garden width w'],{sourceKeys:['arithmetic','vectors'],mathSymbols:['w'],formulaCards:['quadratic-optimization'],grammarCards:['quadratic-optimization'],tokens:['w'],wordMatches:[],relatedIds:['length','local-garden-length','perimeter']});
  add('complex-variable','Complex-number placeholder: z','notation',['z'],'In these complex-number expressions, z is a placeholder for a number in the complex plane. This local domain declaration matters: another expression can use z for something else.','If z=3+4i, then |z|=5.','z, a complex number',['complex variable z'],{sourceKeys:['complex','dlmfNotation'],mathSymbols:['z'],formulaCards:['complex-multiplication'],wordMatches:[],relatedIds:['complex-number','complex-modulus','real-part','imaginary-part']});
  add('vector-space-label','Vector-space label: V','notation',['V'],'In dimension notation dim(V), V names the vector space being discussed. The capital letter itself is a label, not a fixed numerical value.','If V is the real plane, dim(V)=2.','V, the declared vector space',['vector space V'],{sourceKeys:['basis'],mathSymbols:['V'],formulaCards:[],wordMatches:[],relatedIds:['vector-space-dimension','basis','subspace']});
  add('angle-brackets','Angle brackets','notation',['⟨','⟩'],'Angle brackets can enclose vector components or the two inputs of an inner product, depending on the stated convention. They are not automatically inequality signs or multiplication operators.','⟨1,2⟩ can list two components; ⟨u,v⟩ can denote an inner product.','angle brackets',['angle brackets'],{sourceKeys:['vectors','dlmfNotation'],lookupAliases:['\\langle','\\rangle'],wordMatches:['angle brackets'],relatedIds:['dot-product','coordinate-vector','ordered-pair']});
  Object.assign(sources,{
    chainRule:{title:'OpenStax · The Chain Rule',url:'https://openstax.org/books/calculus-volume-1/pages/3-6-the-chain-rule'},
    fields:{title:'OpenStax · Functions of Several Variables: graphs and level curves',url:'https://openstax.org/books/calculus-volume-3/pages/4-1-functions-of-several-variables'},
    tangentPlanes:{title:'OpenStax · Tangent Planes and Linear Approximations',url:'https://openstax.org/books/calculus-volume-3/pages/4-4-tangent-planes-and-linear-approximations'},
    extrema:{title:'OpenStax · Maxima/Minima Problems: critical and saddle points',url:'https://openstax.org/books/calculus-volume-3/pages/4-7-maxima-minima-problems'}
  });
  add('chain-rule','Chain rule','calculus',["(f∘g)′(x)=f′(g(x))g′(x)"],'If g is differentiable at x and f is differentiable at g(x), the derivative of their composition is f′(g(x))g′(x). Evaluate the outer derivative at the inner value, then multiply the signed local rates; do not add them.','For f(u)=u² and g(x)=2x+1, at x=1 the derivative is 6×2=12.','derivative of f composed with g',['chain rule','composite derivative','composite sensitivity','local sensitivity'],{sourceKeys:['chainRule'],lookupAliases:["(f\\circ g)'(x)","f'(g(x))g'(x)",'d(f(g(x)))/dx'],relatedIds:['composition','derivative','differentiability','rate']});
  add('differentiability','Differentiability','calculus',[],'A function has a local linear approximation whose error becomes small compared with the input-step size. For several inputs, having coordinate partial derivatives alone does not guarantee this property. In one input, differentiability is the existence of the derivative.','For F(x,y)=x²+y² near (1,0), F is approximated by 1+2(x−1).','differentiability',['differentiable','total differentiability'],{sourceKeys:['tangentPlanes'],relatedIds:['derivative','partial-derivative','linear-approximation','continuity']});
  add('scalar-field','Scalar field','calculus',['F'],'A function assigning one scalar value to each position in its domain. In these two field cards, F takes a plane point (x,y) as input; F(x,y) is its value, distinct from its gradient vector.','F(x,y)=x²+y² assigns value 1 to the point (1,0).','F, a scalar field',['scalar field','scalar fields'],{sourceKeys:['fields'],tokens:['F'],mathSymbols:['F'],formulaCards:['partial-derivative','gradient'],grammarCards:['partial-derivative','gradient'],wordMatches:['scalar field','scalar fields'],relatedIds:['function','scalar','height-field','gradient']});
  add('graph-surface','Graph surface','calculus',[],'The geometric graph of a two-input scalar function consists of points (x,y,F(x,y)). Its third coordinate displays the output value; it does not introduce a third independent input.','The graph of F(x,y)=x²+y² contains the point (1,0,1).','surface graph of F',['surface','surface graph','function surface'],{sourceKeys:['fields'],wordMatches:['surface','surface graph','graph surface'],relatedIds:['scalar-field','height-field','cross-section','tangent-plane']});
  add('height-field','Height field','calculus',[],'A scalar field interpreted as a height at each input position. This interpretation explains a surface view; physical altitude and units must still be specified by the story. Height is the field value, not a partial derivative or gradient norm.','If F(1,0)=1, the graph at that input has displayed height 1.','height field',['height field','height model','field height'],{sourceKeys:['fields'],wordMatches:['height field','height model','field height'],relatedIds:['scalar-field','graph-surface','level-set','gradient']});
  add('level-set','Level set and contour','calculus',[],'Inputs where a scalar function takes one fixed value. In two input dimensions these sets are often drawn as level curves or contours. A level set can also be empty, a point, or a degenerate set; it need not always be a smooth curve.','For F(x,y)=x²+y², level 1 is a circle and level 0 is the origin.','level set; level curve; contour',['level set','level sets','level curve','level curves','contour','contours'],{sourceKeys:['fields','gradient'],relatedIds:['scalar-field','graph-surface','gradient','critical-point']});
  add('cross-section','Coordinate cross-section','calculus',[],'Hold one input fixed and trace the function as another input varies. A coordinate slice of a surface gives a one-input curve; its local slope is the corresponding partial derivative where that derivative exists.','For F(x,y)=x²+y², fixing y=1 gives the curve F(x,1)=x²+1.','coordinate slice; cross-section',['cross-section','cross section','coordinate slice','slice'],{sourceKeys:['fields','partial'],wordMatches:['cross-section','cross section','coordinate slice','x-slice','y-slice'],relatedIds:['partial-derivative','graph-surface','tangent']});
  add('directional-derivative','Directional derivative','calculus',['DᵤF','∇F·u'],'A local rate in a chosen unit direction. For a differentiable scalar field, DᵤF=∇F·u when ‖u‖=1. The unit-length condition makes this a rate per unit input distance; using an unnormalized vector changes the scale.','For F=x²+y² at (1,0), direction u=(1,0) gives rate 2.','directional derivative of F in unit direction u',['directional derivative','directional derivatives','directional rate','directional slope'],{sourceKeys:['gradient'],lookupAliases:['D_uF','D_u F','D_u f','\\nabla F\\cdot u'],relatedIds:['gradient','unit-vector','dot-product','differentiability']});
  add('unit-gradient','Unit gradient direction','calculus',['∇F/‖∇F‖'],'When the gradient is nonzero, divide it by its norm to obtain a unit direction. For a differentiable scalar field in Euclidean coordinates, it gives greatest first-order increase. At zero gradient this normalization is undefined and no unique unit uphill direction is supplied.','A gradient (3,4) has unit direction (3/5,4/5).','normalized gradient; unit gradient',['unit gradient','normalized gradient','gradient direction'],{sourceKeys:['gradient'],lookupAliases:['\\nabla F/\\lVert\\nabla F\\rVert'],relatedIds:['gradient','magnitude','unit-vector','stationary-point']});
  add('critical-point','Critical point','calculus',[],'For a function defined around a point, a critical point has all first partial derivatives zero or has a required first partial derivative that does not exist. In the smooth polynomial field cards, only the zero-gradient case occurs. This alone does not classify an extremum.','For F=x²−y², the origin is critical but is neither a local maximum nor a local minimum.','critical point',['critical point','critical points'],{sourceKeys:['extrema'],relatedIds:['stationary-point','partial-derivative','saddle-point','local-extremum']});
  add('stationary-point','Stationary point','calculus',['∇F=0'],'A differentiable point where the derivative is zero in one input, or the gradient is the zero vector in several inputs. It can be a minimum, maximum, saddle, or part of a flat region.','F=x²−y² has a stationary point at (0,0).','stationary point; zero gradient',['stationary point','stationary points','zero gradient'],{sourceKeys:['extrema','gradient'],relatedIds:['gradient','critical-point','saddle-point','local-extremum']});
  add('tangent-plane','Tangent plane','calculus',[],'For the graph of a differentiable two-input function, the plane given by its local linear approximation at a point. Its two coordinate slopes are the partial derivatives. A plane generally has different slopes in different directions.','For F=x²+y² at (1,0), the tangent plane has height 2x−1.','tangent plane',['tangent plane','tangent planes'],{sourceKeys:['tangentPlanes'],relatedIds:['partial-derivative','linear-approximation','directional-derivative','graph-surface']});
  add('saddle-point','Saddle point','calculus',[],'In this smooth-function setting, an interior stationary point with both higher and lower function values arbitrarily nearby. It is neither a local maximum nor a local minimum. A zero gradient by itself does not establish a saddle.','At the origin, F=x²−y² rises along the x-axis and falls along the y-axis.','saddle point',['saddle point','saddle points','saddle'],{sourceKeys:['extrema'],relatedIds:['stationary-point','critical-point','local-extremum','level-set']});
  add('linear-approximation','First-order linear approximation','calculus',[],'Approximate a differentiable function near a point using its value and derivative information there. The formula retains constant and linear input changes; it need not predict a finite change exactly.','For f(x)=x² near 1, the estimate at 1.1 is 1.2, while the exact value is 1.21.','first-order approximation; linear approximation',['linear approximation','first-order approximation','first-order estimate','first-order local approximation'],{sourceKeys:['tangentPlanes','derivative'],wordMatches:['linear approximation','first-order approximation','first-order estimate','first-order local approximation','first-order sensitivity'],relatedIds:['differentiability','derivative','tangent-plane','increment']});
  add('local-extremum','Local maximum and minimum','calculus',[],'A local maximum is at least as large as nearby function values; a local minimum is at most as large. A global extremum compares the entire stated domain. Interior differentiable extrema must be stationary, but a stationary point need not be an extremum.','F=−x²−y² has a local maximum at (0,0).','local maximum; local minimum',['local maximum','local minimum','local maxima','local minima','local extremum','local extrema'],{sourceKeys:['extrema'],relatedIds:['maximum','minimum','stationary-point','saddle-point']});
  add('local-chain-inner-value','Inner value label: u','notation',['u'],'In the chain-rule card, u=g(x) is the scalar value output by the inner function and supplied to the outer function. The function g and its value u are different mathematical objects. Another module may use u for a vector.','With g(x)=2x+1 and x=1, u=3.','u, the inner value',['inner value u'],{sourceKeys:['chainRule'],tokens:['u'],mathSymbols:['u'],formulaCards:['chain-rule'],grammarCards:['chain-rule'],wordMatches:[],relatedIds:['chain-rule','function-notation','input','output']});
  add('smoothness','Smoothness','calculus',[],'Smoothness describes differentiability with regularity. The precise number of continuous derivatives required depends on a text’s convention. In these polynomial models, derivatives of every order exist continuously; a smooth-looking picture alone proves no such condition.','F=x²+y² is smooth, regardless of how finely its graph is drawn.','smoothness',['smooth function','smooth field','smooth height model','smooth polynomial','smooth surface'],{sourceKeys:['tangentPlanes','chainRule'],wordMatches:['smooth function','smooth field','smooth height model','smooth polynomial','smooth surface'],relatedIds:['differentiability','continuity','higher-derivative']});
  sources.graphs={title:'Cornell CS2110 · Shortest Paths: vertices, labels and edges',url:'https://courses.cis.cornell.edu/courses/cs2110/2026sp/lectures/lec23/'};
  sources.triangleGeometry={title:'OpenStax · Triangles: congruence and similarity',url:'https://openstax.org/books/contemporary-mathematics/pages/10-3-triangles'};
  Object.assign(sources,{
    optimization:{title:'Boyd and Vandenberghe · Convex Optimization: objective functions and convexity',url:'https://www.stanford.edu/~boyd/cvxbook/bv_cvxbook.pdf'},
    descentNotes:{title:'Stanford EE364a · Unconstrained Minimization: gradient descent and step size',url:'https://web.stanford.edu/class/ee364a/lectures/unconstrained.pdf'},
    sequences:{title:'OpenStax · Sequences: recurrence, convergence and divergence',url:'https://openstax.org/books/calculus-volume-2/pages/5-1-sequences'}
  });
  add('gradient-descent','Gradient descent','calculus',[],'An iterative method that subtracts a chosen positive multiple of the current gradient to seek a smaller objective value. A direction of local decrease does not make every finite step safe; convergence requires conditions on the function and step choices.','For C(x)=x²/2, subtracting 0.4 times its derivative maps 2 to 1.2.','gradient descent',['gradient descent','gradient-descent','steepest descent in Euclidean coordinates'],{sourceKeys:['descentNotes'],wordMatches:['gradient descent','gradient-descent'],relatedIds:['gradient','cost-function','step-size','iterate','convergence','descent-direction']});
  add('cost-function','Cost or objective function','calculus',['C','C(xₖ,yₖ)'],'A scalar function whose value an optimization problem seeks to minimize or maximize. A cost or loss is usually minimized. The function and its current numerical value are distinct objects.','For C(x,y)=(x²+2y²)/2, C(2,1.5)=4.25.','C, the cost function; C at the current iterate',['cost function','objective function','loss function','cost','objective'],{sourceKeys:['optimization'],tokens:['C','C(xₖ,yₖ)'],mathSymbols:['C'],grammarCards:['gradient-descent'],formulaCards:['gradient-descent'],wordMatches:['cost function','objective function','loss function','objective'],lookupAliases:['C(x_k,y_k)','C(x_{k},y_{k})'],relatedIds:['scalar-field','function-notation','minimum','gradient-descent','strict-convexity']});
  add('step-size','Step size or learning rate','calculus',['η'],'The multiplier controlling an iterative update. In gradient descent it scales the negative gradient; the actual displacement also depends on the gradient. Its units and admissible values belong to the model. A larger setting can overshoot.','For derivative 3 and step size 0.1, the gradient-descent displacement is −0.3.','eta, the step-size parameter',['step size','step sizes','step-size','learning rate','learning rates','learning-rate'],{sourceKeys:['descentNotes'],tokens:['η'],mathSymbols:['η'],grammarCards:['gradient-descent'],formulaCards:['gradient-descent'],wordMatches:['step size','step sizes','step-size','learning rate','learning rates','learning-rate'],relatedIds:['gradient-descent','parameter','descent-direction','overshoot','iteration-stability','eta']});
  add('iterate','Iterate','dynamics',['xₖ','yₖ','xₖ₊₁','yₖ₊₁'],'One state produced by an iterative rule. An iterate is a result; iteration is the repeated process. The next iterate uses the current state, rather than restarting from the original one.','For xₖ₊₁=0.5xₖ and x₀=2, the next iterates are 1, 0.5 and 0.25.','x sub k; y sub k; the current or next iterate',['iterates','iteration state','next iterate','current iterate'],{sourceKeys:['sequences'],tokens:['xₖ','yₖ','xₖ₊₁','yₖ₊₁'],grammarCards:['gradient-descent'],formulaCards:['gradient-descent'],wordMatches:['iterate','iterates','iteration state'],lookupAliases:['x_k','y_k','x_{k}','y_{k}','x_{k+1}','y_{k+1}'],relatedIds:['iteration','iteration-index','initial-value','sequence','gradient-descent']});
  add('iteration-index','Iteration index','dynamics',['k'],'A whole-number label counting completed updates in this card. k=0 denotes the initial state; k+1 names the next update. It is a discrete index, not elapsed physical time or a fractional update.','With k=4, four updates have been completed from the k=0 state.','k, the number of completed updates',['iteration count','iteration index','update count','completed iterations'],{sourceKeys:['sequences'],tokens:['k'],mathSymbols:['k'],grammarCards:['gradient-descent'],formulaCards:['gradient-descent'],wordMatches:['iteration count','iteration index','update count','completed iterations'],relatedIds:['iterate','iteration','subscript','integer','initial-value']});
  add('convergence','Convergence of a sequence','dynamics',[],'A sequence converges to a finite limit if its terms eventually remain within every chosen positive distance of that limit. A finite displayed path alone cannot establish this infinite-sequence claim. Oscillating terms can still converge.','The sequence 2, 1, 0.5, 0.25, … converges to 0.','sequence convergence',['convergence','convergent','converges','converging'],{sourceKeys:['sequences'],wordMatches:['convergence','convergent','converges','converging'],relatedIds:['sequence','limit','iteration','contraction-factor','oscillation']});
  add('contraction-factor','Coordinate contraction factor','dynamics',[],'For a coordinate recurrence xₖ₊₁=q xₖ, q multiplies that coordinate at every update. Nonzero coordinates shrink in magnitude when |q|<1; a negative q also reverses their sign. The label does not assert that every possible step choice contracts.','With q=−0.5, the iterates 2, −1, 0.5, −0.25 alternate while shrinking.','coordinate multiplier or contraction factor',['contraction factor','contraction factors','coordinate multiplier','coordinate multipliers'],{sourceKeys:['descentNotes','sequences'],wordMatches:['contraction factor','contraction factors','coordinate multiplier','coordinate multipliers'],relatedIds:['convergence','iteration-stability','absolute-value','oscillation','step-size']});
  add('iteration-stability','Iteration stability','dynamics',[],'How an update rule responds to small changes in a state. In the displayed coordinate recurrence, |q|<1 damps changes, |q|=1 preserves their magnitude, and |q|>1 amplifies them. A bounded finite plot is not a general stability proof.','For xₖ₊₁=−xₖ, a nonzero coordinate repeats two values rather than approaching 0.','stability of the iterative update',['iteration stability','stable step','stable steps','stability condition','stability bound','unstable step','unstable steps'],{sourceKeys:['descentNotes','sequences'],wordMatches:['iteration stability','stable step','stable steps','stability condition','stability bound','unstable step','unstable steps'],relatedIds:['contraction-factor','convergence','step-size','perturbation']});
  add('strict-convexity','Strict convexity','calculus',[],'A function on a convex domain is strictly convex if its value between any two distinct inputs lies strictly below the corresponding weighted average of their values. If a minimum is attained, it is unique; strict convexity alone does not ensure attainment.','C(x,y)=(x²+2y²)/2 is strictly convex and has its unique minimum at (0,0).','strict convexity',['strict convexity','strictly convex','strictly convex quadratic'],{sourceKeys:['optimization'],wordMatches:['strict convexity','strictly convex'],relatedIds:['convex-combination','cost-function','minimum','local-extremum','gradient-descent']});
  add('approximation-error','Signed approximation error','calculus',['R'],'The difference between a stated exact value and its approximation, with the subtraction order declared. In the tangent-plane card R=actual−predicted, so negative error means the plane predicts too high. Its sign differs from its nonnegative magnitude.','If actual height is 2.8975 and predicted height is 2.9875, R=−0.09.','R, actual value minus predicted value',['approximation error','signed approximation error','prediction error','linearization error','remainder'],{sourceKeys:['tangentPlanes'],tokens:['R'],mathSymbols:['R'],grammarCards:['tangent-plane'],formulaCards:['tangent-plane'],wordMatches:['approximation error','signed approximation error','prediction error','linearization error'],relatedIds:['linear-approximation','tangent-plane','subtraction','absolute-value']});
  add('overshoot','Overshoot in an update','dynamics',[],'An update crosses a target or reference point. In the one-coordinate quadratic examples it crosses the minimizing coordinate. Crossing that coordinate does not itself imply increasing cost: the new point can still be closer.','The update 2 → −1 overshoots 0 while reducing x²/2 from 2 to 0.5.','overshoot',['overshoot','overshoots','overshooting'],{sourceKeys:['descentNotes'],wordMatches:['overshoot','overshoots','overshooting'],relatedIds:['step-size','oscillation','cost-function','iteration-stability']});
  add('oscillation','Oscillation','dynamics',[],'Repeated movement across a reference value or between sides. Its size may shrink, stay fixed or grow. Alternation alone does not decide convergence. This sequence meaning is distinct from assuming a physical oscillating system.','The sequence 1, −0.5, 0.25, −0.125, … oscillates and converges to 0.','oscillation',['oscillations','oscillate','oscillates','oscillating','alternating iterates'],{sourceKeys:['sequences','oscillator'],wordMatches:['oscillation','oscillations','oscillate','oscillates','oscillating','alternating iterates'],relatedIds:['convergence','overshoot','contraction-factor','iteration']});
  add('descent-direction','Descent direction','calculus',[],'At a differentiable point, a direction with negative directional derivative. A sufficiently small positive move lowers the function. A nonzero negative gradient is one such direction in Euclidean coordinates; an oversized finite move can still raise the cost.','For C=x²/2 at x=2, direction −1 gives directional derivative −2.','direction of local decrease',['descent direction','negative gradient direction','direction of decrease'],{sourceKeys:['descentNotes','gradient'],wordMatches:['descent direction','negative gradient direction','direction of decrease'],relatedIds:['directional-derivative','gradient','gradient-descent','step-size']});
  add('logarithmic-display','Logarithmic cost display','functions',['ln(1+C)'],'A shifted natural-log display places nonnegative dimensionless cost C at vertical position ln(1+C), using base e. It preserves zero and ordering while compressing large values. Equal vertical gaps are not equal cost differences. This changes drawing coordinates; the original cost remains available.','C=0 gives ln(1)=0; C=1 gives ln(2)≈0.6931.','natural logarithm of one plus the normalized cost',['logarithmic display','logarithmic cost display','shifted logarithmic display','natural-log cost display','compressed cost display'],{sourceKeys:['exp','logs'],tokens:['ln(1+C)'],mathSymbols:['ln(1+C)'],lookupAliases:['\\ln(1+C)'],formulaCards:['gradient-descent'],wordMatches:['logarithmic display','logarithmic cost display','shifted logarithmic display','natural-log cost display','compressed cost display'],relatedIds:['logarithm','cost-function','eulers-number','gradient-descent']});
  Object.assign(sources,{
    statisticsTerms:{title:'OpenStax · Statistics: Population, Sample and Key Terms',url:'https://openstax.org/books/introductory-statistics-2e/pages/1-1-definitions-of-statistics-probability-and-key-terms'},
    statisticsMean:{title:'OpenStax · Measures of the Center of the Data',url:'https://openstax.org/books/introductory-statistics-2e/pages/2-5-measures-of-the-center-of-the-data'},
    statisticsCensus:{title:'OpenStax · Measures of Spread: Census and Sample',url:'https://openstax.org/books/introductory-statistics-2e/pages/2-7-measures-of-the-spread-of-the-data'},
    algorithmAnalysis:{title:'University of Washington · Algorithm Analysis I Study Guide',url:'https://courses.cs.washington.edu/courses/cse373/20wi/lectures/04-algo_analysis_1/guide/'},
    bigO:{title:'NIST Dictionary of Algorithms and Data Structures · Big-O Notation',url:'https://xlinux.nist.gov/dads/HTML/bigOnotation.html'},
    bigTheta:{title:'NIST Dictionary of Algorithms and Data Structures · Theta',url:'https://xlinux.nist.gov/dads/HTML/theta.html'},
    linearTime:{title:'NIST Dictionary of Algorithms and Data Structures · Linear',url:'https://xlinux.nist.gov/dads/HTML/linear.html'},
    sequenceIndex:{title:'Python documentation · Common Sequence Operations: index origin zero',url:'https://docs.python.org/3/library/stdtypes.html#common-sequence-operations'}
  });
  add('universal-set','Universal set','sets',['U'],'The stated collection containing every object currently under discussion. Membership, complements and set operations are interpreted relative to that universe; U is a local name, not the set of everything.','For a peg inventory, U={1,2,…,12}.','U, the stated universe',['universe','universe of discourse','universal set'],{sourceKeys:['reading'],tokens:['U'],mathSymbols:['U'],grammarCards:['set'],formulaCards:['set'],relatedIds:['set','element','set-complement','cardinality']});
  add('cardinality','Cardinality','sets',['|A|','|B|','|U|','|R|','|A∩B|','|A∪B|','|A∖B|'],'The number of distinct elements of a finite set. Bars around a declared set count its members; bars around a scalar can instead mean absolute value. Cardinality is a count, not an interval length or the set itself.','If R={4,5,6,7}, then |R|=4.','number of elements in the stated set',['cardinality','cardinalities','set size','number of elements'],{sourceKeys:['reading'],tokens:['|A|','|B|','|U|','|R|','|A∩B|','|A∪B|','|A∖B|'],grammarCards:['set'],formulaCards:['set'],lookupAliases:['|A\\cap B|','|A\\cup B|','|A\\setminus B|'],relatedIds:['set','element','empty-set','absolute-value','natural-number']});
  add('arithmetic-mean','Arithmetic mean','chance',[],'Add the numerical observations and divide by their count. This summary retains the observations’ units. Equal weighting is part of this definition; another weighting rule gives a different mean.','The arithmetic mean of 2,4,9 is (2+4+9)/3=5.','arithmetic mean',['arithmetic mean','mean','average','averaging'],{sourceKeys:['statisticsMean'],wordMatches:['arithmetic mean','mean of observations'],relatedIds:['addition','division','sample-mean','population-mean']});
  add('population','Population','chance',[],'The complete group of objects or observations defined by a statistical question. A sample selects members of that group. The population must be specified before deciding what a result describes.','All twelve crates in the displayed inventory form this population.','population',['population','populations'],{sourceKeys:['statisticsTerms'],relatedIds:['sample','population-mean','data-value']});
  add('sample','Sample','chance',[],'A selected subset of the population being studied. Its selection rule matters: a fixed chosen block is not a random sample merely because it is smaller than the population.','The last four crates can be a sample of a twelve-crate inventory.','sample',['sample','samples','selected subset'],{sourceKeys:['statisticsTerms'],relatedIds:['population','sample-size','sample-mean','zero-based-index']});
  add('population-mean','Population mean','chance',['μ'],'The arithmetic mean of all observations in the stated finite population. Here μ is calculated from the known complete inventory; it is separate from the mean of the selected sample.','For twelve crates totaling 129 kg, μ=129/12=10.75 kg.','mu, the population mean',['population mean','whole-population mean'],{sourceKeys:['statisticsMean'],tokens:['μ'],mathSymbols:['μ'],grammarCards:['population-sample'],formulaCards:['population-sample'],lookupAliases:['\\mu'],wordMatches:['population mean','whole-population mean'],relatedIds:['population','arithmetic-mean','sample-mean','mu']});
  add('sample-mean','Sample mean','chance',['x̄'],'The arithmetic mean of the selected observations: their sum divided by the positive sample size. A selected sample’s mean need not equal the population mean; a particular difference is not itself an inference about uncertainty.','For selected crate weights 12, 12, 13, 14 kg, x̄=51/4=12.75 kg.','x bar, the sample mean',['sample mean','sample average','x bar','xbar'],{sourceKeys:['statisticsMean'],tokens:['x̄'],mathSymbols:['x̄'],grammarCards:['population-sample'],formulaCards:['population-sample'],lookupAliases:['\\bar{x}','\\overline{x}','xbar'],wordMatches:['sample mean','sample average','x bar'],relatedIds:['sample','sample-size','arithmetic-mean','population-mean','mean-difference']});
  add('mean-difference','Sample–population mean difference','chance',['E'],'The signed sample mean minus the population mean in this lesson. Positive means the selected group averages higher; negative means lower. This exact comparison of known data is not a confidence interval or a probability claim.','If x̄=12.75 kg and μ=10.75 kg, then E=2 kg.','sample mean minus population mean',['mean difference','sample-population difference','sample–population mean difference'],{sourceKeys:['statisticsTerms','statisticsMean'],tokens:['E'],mathSymbols:['E'],grammarCards:['population-sample'],formulaCards:['population-sample'],wordMatches:['mean difference','sample-population difference','sample–population mean difference'],relatedIds:['sample-mean','population-mean','subtraction']});
  add('data-value','Data value','chance',['xᵢ','Xᵢ'],'One recorded value of a measured variable. An index identifies which observation is meant; its position is separate from its measured amount. Repeated numerical values can belong to different observed objects.','Two crates can each weigh 12 kg while remaining two different observations.','the indexed observation',['data value','data values','observation','observations','measurement','measurements'],{sourceKeys:['statisticsTerms'],tokens:['xᵢ','Xᵢ'],mathSymbols:['xᵢ','Xᵢ'],grammarCards:['population-sample'],formulaCards:['population-sample'],lookupAliases:['x_i','X_i','x_{i}','X_{i}'],relatedIds:['subscript','sample','population','arithmetic-mean']});
  add('sample-size','Sample size','chance',['n'],'The number of observations selected into the sample. It is a positive whole number here and is the denominator of the sample mean. It is not a measured weight or an algorithm’s input size merely because both can use n.','A sample of four crates has n=4.','n, the sample size',['sample size','sample sizes','number of selected observations'],{sourceKeys:['statisticsTerms','statisticsMean'],tokens:['n'],mathSymbols:['n'],grammarCards:['population-sample'],formulaCards:['population-sample'],relatedIds:['sample','cardinality','sample-mean','natural-number']});
  add('population-size','Population size','chance',['N'],'The number of objects in the complete population being studied. N counts the known inventory here, while n counts the selected sample. Repeated measured weights still belong to different counted crates.','A twelve-crate inventory has N=12 even if two crates weigh the same.','capital N, the population size',['population size','whole-population count'],{sourceKeys:['statisticsTerms'],tokens:['N'],mathSymbols:['N'],grammarCards:['population-sample'],formulaCards:['population-sample'],relatedIds:['population','sample-size','cardinality','population-mean']});
  add('census','Census','chance',[],'Observe every member of the defined population rather than selecting only part of it. In this known finite inventory, choosing all twelve crate labels makes the sample and population means agree.','Selecting all twelve known crates is a census of this inventory.','census',['census','all population members'],{sourceKeys:['statisticsCensus'],wordMatches:['census'],relatedIds:['population','sample','population-size','population-mean']});
  add('statistic','Sample statistic','chance',[],'A numerical summary calculated from the selected sample. The sample mean is one statistic; its value describes that selected group and need not equal the corresponding whole-population quantity.','The selected four-crate mean 12.75 kg is a sample statistic.','sample statistic',['sample statistic','statistic','statistics'],{sourceKeys:['statisticsTerms'],wordMatches:['sample statistic','sample statistics','a statistic'],relatedIds:['sample','sample-mean','population-parameter']});
  add('population-parameter','Population parameter','chance',[],'A numerical characteristic of the complete population. The known twelve-crate mean is one population parameter here. This statistical meaning differs from a playground parameter chosen to configure a calculation.','The complete twelve-crate mean 10.75 kg is a population parameter.','population parameter',['population parameter','statistical parameter'],{sourceKeys:['statisticsTerms'],wordMatches:['population parameter','statistical parameter'],relatedIds:['population','population-mean','statistic','parameter']});
  add('zero-based-index','Zero-based index','discrete',['s'],'A position convention in which the first item has index 0, the second index 1, and so on. The displayed crate sample starts at s; wrapping to the beginning is an explicitly declared selection rule.','In a twelve-item list, valid zero-based positions run from 0 through 11.','s, a position counted from zero',['zero-based index','zero based index','zero-based position','starting index'],{sourceKeys:['sequenceIndex'],tokens:['s'],mathSymbols:['s'],grammarCards:['population-sample'],formulaCards:['population-sample'],relatedIds:['subscript','sample','sample-size']});
  add('algorithm','Algorithm','discrete',[],'A specified procedure for carrying out a computation. To discuss its resource use, state the input, the operations performed and the cost model. A particular measured run is separate from the procedure’s general growth behavior.','Inspect every item in a list once, then stop.','algorithm',['algorithm','algorithms','procedure'],{sourceKeys:['algorithmAnalysis'],relatedIds:['operation-count','input-size','cost-model','computational-complexity']});
  add('computational-complexity','Computational complexity','discrete',[],'How a stated resource measure changes with input size for an algorithm family under a stated computation model. Operation counts, memory and elapsed time are different measures; bounded drawings do not establish an asymptotic theorem.','A full scan with one counted operation per item has work w(n)=n.','computational complexity',['computational complexity','algorithm analysis','running-time analysis'],{sourceKeys:['bigO','algorithmAnalysis'],relatedIds:['algorithm','input-size','operation-count','cost-model','big-o','big-theta']});
  add('input-size','Input size','discrete',['n','2n'],'The quantity measuring how large an algorithm’s input is. In the scan lesson n is the number of items; 2n describes a second input with twice as many. Other problems can use a different size measure.','A twelve-item input has n=12; the comparison input has 2n=24.','n, the input size',['input size','problem size','input length'],{sourceKeys:['bigO'],tokens:['n','2n'],mathSymbols:['n','2n'],grammarCards:['computational-complexity'],formulaCards:['computational-complexity'],relatedIds:['algorithm','operation-count','linear-time']});
  add('operation-count','Operation count','discrete',['w(n)'],'The number of executions of the particular operation chosen for analysis. The full-scan model counts one visit per item, so w(n)=n. This count remains n even when a stipulated time cost is zero.','For twelve items, w(12)=12 counted visits.','w of n, counted operations',['operation count','counted operation','counted operations','full scan','full-scan','item visit'],{sourceKeys:['algorithmAnalysis'],tokens:['w(n)'],mathSymbols:['w(n)'],grammarCards:['computational-complexity'],formulaCards:['computational-complexity'],relatedIds:['algorithm','input-size','cost-model','big-theta']});
  add('cost-model','Cost model','discrete',['c','T(n)','T(2n)'],'A declaration of what work is counted and how cost is assigned to it. Here every item costs c milliseconds, giving modeled times T(n)=cn and T(2n)=2cn. These are stipulated calculations, not machine benchmarks.','For c=2 ms/item and n=12, the modeled time is 24 ms.','c per item and T of n modeled time',['cost model','per-item cost','cost per item','modeled time','constant work per item'],{sourceKeys:['algorithmAnalysis'],tokens:['c','T(n)','T(2n)'],mathSymbols:['c','T(n)','T(2n)'],grammarCards:['computational-complexity'],formulaCards:['computational-complexity'],lookupAliases:['T(2*n)'],relatedIds:['operation-count','input-size','linear-time','compound-unit']});
  add('linear-time','Linear-time algorithm','discrete',[],'Under a stated cost model, resource use is bounded above by a constant times input size for sufficiently large inputs. A full scan performing one visit per item has the tighter Θ(n) operation count. This meaning of linear differs from linear algebra.','For w(n)=n, doubling n doubles the exact counted work.','linear time',['linear time','linear-time','linear-time algorithm','linear-time algorithms','linear algorithms'],{sourceKeys:['linearTime','algorithmAnalysis'],wordMatches:['linear time','linear-time','linear-time algorithm','linear-time algorithms','linear algorithms'],relatedIds:['algorithm','big-o','big-theta','operation-count','cost-model']});
  add('big-o','Big-O upper bound','discrete',['O(n)'],'An eventual upper bound: beyond a fixed input-size threshold, nonnegative work is at most a fixed positive constant times n. The constant and threshold do not depend on n. O(n) is not an exact equality or a claim derived from a finite chart.','w(n)=3n+2 is O(n).','big O of n',['big O','big-O','big oh','asymptotic upper bound','O(n)'],{sourceKeys:['bigO'],tokens:['O(n)'],mathSymbols:['O(n)'],grammarCards:['computational-complexity'],formulaCards:['computational-complexity'],lookupAliases:['O(n)','O (n)'],relatedIds:['big-theta','linear-time','computational-complexity','input-size']});
  add('big-theta','Big-Theta tight bound','discrete',['Θ(n)'],'An eventual two-sided bound: beyond a fixed threshold, nonnegative work lies between two fixed positive multiples of n. Both a lower and an upper bound are required. This class does not name an angle, even though its symbol is capital Greek theta.','w(n)=n is Θ(n); modeled T(n)=cn is Θ(n) when fixed c>0.','big theta of n',['big Theta','big-Theta','tight bound','asymptotically tight bound'],{sourceKeys:['bigTheta'],tokens:['Θ(n)'],mathSymbols:['Θ(n)'],grammarCards:['computational-complexity'],formulaCards:['computational-complexity'],lookupAliases:['\\Theta(n)'],relatedIds:['big-o','linear-time','operation-count','theta-capital']});
  Object.assign(sources,{
    conditional:{title:'OpenStax · Statistics terminology and conditional probability',url:'https://openstax.org/books/introductory-statistics-2e/pages/3-1-terminology'},
    uniform:{title:'OpenStax · The Uniform Distribution',url:'https://openstax.org/books/introductory-statistics-2e/pages/5-2-the-uniform-distribution'},
    spread:{title:'OpenStax · Measures of the Spread of the Data',url:'https://openstax.org/books/introductory-statistics-2e/pages/2-7-measures-of-the-spread-of-the-data'},
    sequences:{title:'OpenStax · Sequences and Their Notations',url:'https://openstax.org/books/precalculus-2e/pages/11-1-sequences-and-their-notations'},
    geometricSequences:{title:'OpenStax · Geometric Sequences',url:'https://openstax.org/books/precalculus-2e/pages/11-3-geometric-sequences'}
  });
  add('uniform-distribution','Uniform distribution','chance',[],'A probability model that spreads probability evenly over its allowed outcomes. For a location uniform on an interval, the probability of a subinterval is its length divided by the whole interval length; an individual point has probability zero.','A location uniform on a 100 cm strip falls in its first 24 cm with probability 24/100.','uniform distribution',['uniform location','uniformly','uniform probability','uniformly sampled'],{sourceKeys:['uniform'],relatedIds:['probability','event','conditional-probability','interval']});
  add('conditioning-event','Conditioning event','chance',['B'],'The event assumed to have occurred when computing a conditional probability. Its probability must be positive in the elementary ratio P(A|B)=P(A∩B)/P(B). Conditioning changes the reference group, not the definition of A.','If B is the first 40 cm of a uniform strip, only that window is the denominator after learning B occurred.','event B, the conditioning event',['conditioning event','given event','inspection window'],{sourceKeys:['conditional','uniform'],grammarCards:['conditional-probability'],formulaCards:['conditional-probability'],tokens:['B'],relatedIds:['conditional-probability','event','denominator']});
  add('population-variance','Population variance','chance',['σ²'],'For a complete finite group of N measured values, the mean squared deviation from its mean μ: σ²=∑(xᵢ−μ)²/N. The variance has squared measurement units. This descriptive calculation divides by N, not N−1.','Lengths 8,10,12,14 cm have mean 11 cm and population variance (9+1+1+9)/4=5 cm².','sigma squared, population variance',['population variance','complete-group variance'],{sourceKeys:['spread'],tokens:['σ²'],grammarCards:['variance'],formulaCards:['variance'],relatedIds:['variance','population-mean','deviation','squared-deviation','standard-deviation']});
  add('deviation','Deviation from the mean','chance',['xᵢ−μ'],'A signed difference between an observation and its stated mean. Positive deviations are above the mean; negative deviations are below it. The deviations from the arithmetic mean sum to zero.','For a 14 cm strap and mean 11 cm, the deviation is 14−11=3 cm.','x subscript i minus mu',['deviation','deviations','signed deviation'],{sourceKeys:['spread'],grammarCards:['variance'],formulaCards:['variance'],relatedIds:['data-value','population-mean','squared-deviation','subtraction']});
  add('squared-deviation','Squared deviation','chance',['(xᵢ−μ)²'],'The square of a signed deviation from a mean. It is nonnegative and uses squared units. Averaging the squared deviations over a complete group gives its population variance.','A deviation of −3 cm has squared deviation (−3)²=9 cm².','the square of x subscript i minus mu',['squared deviation','squared deviations','squared distance from the mean'],{sourceKeys:['spread'],grammarCards:['variance'],formulaCards:['variance'],relatedIds:['deviation','population-variance','square','powered-unit']});
  add('recurrence','Recurrence relation','discrete',[],'A rule that specifies sequence terms from earlier terms, together with enough starting values to determine the sequence. The example vₖ₊₁=rvₖ+d retains a fraction of the current volume and then adds a fixed refill.','With v₀=20 L, r=0.75 and d=3 L, the next volume is v₁=0.75×20+3=18 L.','recurrence relation',['recurrence','recurrence relation','recurrence relations','recursive rule','recursive sequence'],{sourceKeys:['sequences','geometricSequences'],relatedIds:['sequence','initial-value','iteration','retained-fraction','refill-increment','finite-geometric-sum']});
  add('retained-fraction','Retained fraction','discrete',['r'],'The fraction of the current quantity kept during one update. In the reservoir model 0≤r≤1, and retention happens before the fixed refill is added. It describes a fraction of volume, not a chance of an event.','Retaining r=0.75 of 20 L keeps 15 L before any refill.','r, the retained fraction',['retained fraction','retention','retains'],{sourceKeys:['sequences'],tokens:['r'],grammarCards:['recurrence'],formulaCards:['recurrence'],relatedIds:['fraction','ratio','scalar-multiplication','recurrence']});
  add('refill-increment','Fixed refill increment','discrete',['d'],'The same amount added after each retention step in this recurrence. It has the same unit as the sequence values. Its order in the update matters: rv+d generally differs from r(v+d).','After retaining 15 L, a fixed refill d=3 L gives 18 L.','d, the fixed refill increment',['refill','refill increment','fixed refill','fixed addition'],{sourceKeys:['sequences'],tokens:['d'],grammarCards:['recurrence'],formulaCards:['recurrence'],relatedIds:['recurrence','addition','constant','retained-fraction']});
  add('completed-rounds','Completed rounds','discrete',['n'],'The nonnegative whole number of recurrence updates that have actually occurred. At n=0 the sequence remains at its initial value and no retention or refill operation has taken place.','Six complete updates produce v₆. A value n=1.5 is outside this discrete model.','n, completed rounds',['round','rounds','completed rounds','integer rounds'],{sourceKeys:['sequences'],tokens:['n'],grammarCards:['recurrence'],formulaCards:['recurrence'],relatedIds:['iteration','iteration-index','integer','initial-value','recurrence']});
  add('finite-geometric-sum','Finite geometric sum','discrete',[],'A sum of a finite number of successive powers of one ratio. The n-term sum starts with r⁰=1 when n>0; for n=0 the sum is empty and equals zero. No convergence of an infinite series is needed.','For n=3 and r=0.5, 1+r+r²=1+0.5+0.25=1.75.','finite geometric sum',['finite geometric sum','geometric sum','empty sum'],{sourceKeys:['geometricSequences','sequences'],relatedIds:['summation','exponent','recurrence','geometric-sequence']});
  add('geometric-sequence','Geometric sequence','discrete',[],'A sequence obtained by multiplying each term by the same fixed ratio. A recurrence with zero refill has this form. Adding a nonzero refill generally makes the original volume sequence non-geometric.','With no refill, 20,15,11.25,… is geometric with ratio 0.75.','geometric sequence',['geometric sequence','common ratio'],{sourceKeys:['geometricSequences'],relatedIds:['sequence','ratio','recurrence','finite-geometric-sum','exponential']});
  add('interval-length','Interval length','geometry',['ℓ','ℓ(A∩B)'],'The nonnegative length of an interval, measured in a stated length unit. In the nested-strip model, ℓ(A∩B)=min(a,b) centimetres. A length becomes a probability only after division by the length of the appropriate uniform reference interval.','An overlap of 24 cm in a 40 cm conditioning window gives probability 24/40=0.6.','ell, interval length',['interval length','overlap length'],{sourceKeys:['uniform','conditional'],tokens:['ℓ','ℓ(A∩B)'],grammarCards:['conditional-probability'],formulaCards:['conditional-probability'],relatedIds:['interval','measurement-unit-symbols','conditional-probability','ratio']});
  add('probability-normalization','Probability normalization','chance',[],'Rescale the probabilities within a retained event so that the event becomes the whole reference group with total probability one. For P(B)>0, dividing overlap probability by P(B) gives P(A|B). This probability scale is distinct from physical centimetres.','An overlap probability 0.24 within an event of probability 0.4 becomes 0.24/0.4=0.6.','probability normalization',['normalization','normalized','renormalize','renormalized'],{sourceKeys:['conditional','uniform'],relatedIds:['conditional-probability','conditioning-event','probability','ratio']});
  add('retained-volume','Retained volume','discrete',['r vₙ₋₁'],'For a completed retention-then-refill update, the previous volume multiplied by the retained fraction. It is the portion present before adding the refill. At zero completed rounds there is no last update, and the teaching model reports zero retained contribution.','If the previous volume is 20 L and r=0.75, the retained volume is 15 L; adding 3 L gives 18 L.','r times v subscript n minus one',['retained volume','retained portion'],{sourceKeys:['sequences'],grammarCards:['recurrence'],formulaCards:['recurrence'],relatedIds:['retained-fraction','recurrence','multiplication','refill-increment']});
  // First book-guided batch: original definitions, with explicit local roles.
  Object.assign(sources,{
    compoundStatements:{title:'OpenStax · Compound Statements',url:'https://openstax.org/books/contemporary-mathematics/pages/2-2-compound-statements'},
    truthTables:{title:'OpenStax · Truth Tables',url:'https://openstax.org/books/contemporary-mathematics/pages/2-3-truth-tables'},
    structuralDynamics:{title:'Yuriy Vorobets · MATH 614, Lecture 10: Structural stability',url:'https://people.tamu.edu/~yvorobets/MATH614-2016A/Lect1-10web.pdf'},
    scalarDynamics:{title:'John K. Hunter · Discrete Dynamical Systems, §2.12 Stability',url:'https://www.math.ucdavis.edu/~hunter/m207/ch2.pdf'}
  });
  add('logical-connectives','Logical connectives','sets',[],'Operations that form a new statement from one or more statements. In classical truth-functional logic, a connective determines its result from the truth values of its inputs.','Conjunction forms P∧Q and negation forms ¬P.','logical connectives',['connective','logical connective','logical connectives'],{sourceKeys:['compoundStatements','truthTables'],relatedIds:['proposition','truth-value','logical-and','logical-or','logical-not','logical-conditional','if-and-only-if']});
  add('proposition','Proposition','sets',['P','Q'],'A declarative claim treated as true or false in a stated classical interpretation. A sentence with an unassigned free variable may express a predicate rather than a complete proposition.','Here P says the panel length is at least 6 cm; Q says its width is at least 4 cm.','P or Q, a proposition',['proposition','propositions','statement','statements','truth conditions'],{sourceKeys:['logic','compoundStatements'],tokens:['P','Q'],grammarCards:['logical-connectives'],formulaCards:['logical-connectives'],relatedIds:['truth-value','predicate','logical-connectives']});
  add('truth-value','Truth value','sets',['T','F'],'The status true or false assigned to a statement in its stated interpretation. A binary internal encoding of true as 1 and false as 0 is a convention, not a probability or physical measurement.','If a 3 cm panel must be at least 6 cm long, that length proposition is false.','true or false',['truth value','truth values','true','false'],{sourceKeys:['logic','truthTables'],tokens:['T','F'],grammarCards:['logical-connectives','quantifier'],formulaCards:['logical-connectives','quantifier'],wordMatches:['truth value','truth values','true','false'],relatedIds:['proposition','truth-table','truth-constants','probability']});
  add('truth-table','Truth table','sets',[],'A table that lists every assignment of input truth values and the corresponding result of a declared connective or formula. Two independent inputs have four possible assignments.','For conjunction: T∧T is T; T∧F, F∧T and F∧F are F.','truth table',['truth table','truth tables','active truth-table row'],{sourceKeys:['truthTables'],relatedIds:['truth-value','logical-connectives','truth-function','if-and-only-if']});
  add('truth-function','Truth-functionality','sets',[],'A formula is truth-functional when its truth value depends only on the truth values of its parts. This does not preserve every feature of ordinary-language meaning, such as cause, relevance, or contrast.','Material P→Q is false only for true P and false Q; that table alone does not assert that P causes Q.','truth-functionality',['truth functionality','truth-functional','truth-functionality','material truth table'],{sourceKeys:['compoundStatements','truthTables'],relatedIds:['logical-connectives','truth-table','logical-conditional']});
  add('panel-dimensions','Panel dimensions','geometry',['x','y'],'In the panel story, x is its measured length and y its measured width, both in centimetres. These quantities supply inputs to the two threshold propositions; they are not truth values themselves.','For x=3 cm and y=5 cm, x≥6 is false while y≥4 is true.','x, length; y, width',['panel dimensions','panel length','panel width'],{sourceKeys:['compoundStatements'],tokens:['x','y'],grammarCards:['logical-connectives'],formulaCards:['logical-connectives'],relatedIds:['length','proposition','greater-or-equal','measurement-unit-symbols']});
  add('predicate','Predicate','sets',['P(x)'],'A property or relation whose truth depends on its arguments and interpretation. A one-input predicate becomes a statement when a value is supplied, or when its variable is bound by an appropriate quantifier.','For the six strips, P(x) means x≥h; P(8) is true when h=6 cm.','P of x, a predicate',['predicate','predicates','property test','predicate outcomes'],{sourceKeys:['logic'],tokens:['P(x)'],grammarCards:['quantifier'],formulaCards:['quantifier'],relatedIds:['proposition','quantifier','bound-variable','finite-domain']});
  add('quantifier','Quantifier','sets',[],'A logical binder that specifies how a predicate ranges over a declared domain. Universal quantification requires every member to satisfy it; existential quantification requires at least one.','For D={2,4,6,8,10,12} cm, every x in D satisfies x≥2 cm.','quantifier',['quantifier','quantifiers','quantified claim','quantification'],{sourceKeys:['logic'],relatedIds:['for-all','there-exists','predicate','finite-domain','bound-variable','witness','counterexample']});
  add('finite-domain','Finite domain of discourse','sets',['D'],'The explicitly stated finite collection over which a predicate or quantified claim is interpreted. Checking every member settles a claim over that complete finite domain; it does not settle a claim about a larger or infinite collection.','The lesson uses exactly D={2,4,6,8,10,12} cm.','D, the finite domain',['finite domain','finite domain of discourse','stated finite domain','domain of discourse'],{sourceKeys:['logic'],tokens:['D'],grammarCards:['quantifier'],formulaCards:['quantifier'],relatedIds:['set','quantifier','universal-set','cardinality']});
  add('bound-variable','Bound variable','sets',['x'],'A variable occurrence controlled by a quantifier or another binder within its scope. In ∀x∈D P(x), x ranges over the stated domain; h in the predicate x≥h remains a separately assigned parameter.','In ∃x∈D P(x), x is bound and the claim asks whether any domain member satisfies P.','x, the quantified variable',['bound variable','bound variables','variable binding'],{sourceKeys:['logic','reading'],tokens:['x'],grammarCards:['quantifier'],formulaCards:['quantifier'],relatedIds:['quantifier','free-variable','predicate']});
  add('free-variable','Free variable','sets',[],'A variable occurrence not controlled by a binder in the expression under discussion. Its value must be supplied by an assignment before an open predicate can be evaluated.','In P(x): x≥h, h is assigned by the slider; quantifying x does not also bind h.','free variable',['free variable','free variables'],{sourceKeys:['logic','reading'],relatedIds:['variable','bound-variable','quantifier','parameter']});
  add('witness','Witness for an existential claim','sets',[],'An allowed domain member that makes the predicate true, thereby establishing the existential claim in that interpretation. One witness is enough for existence; it need not establish a universal claim.','At h=8 cm, the 10 cm strip is a witness for ∃x∈D P(x).','existential witness',['witness','witnesses','existential witness'],{sourceKeys:['logic','reading'],relatedIds:['there-exists','predicate','finite-domain','counterexample']});
  add('predicate-threshold','Predicate length threshold','sets',['h'],'In the strip predicate P(x): x≥h, the required lower length bound assigned by the slider. Equality qualifies because the comparison is inclusive.','At h=8 cm, lengths 8,10 and 12 cm qualify.','h, the required length threshold',['predicate threshold','required strip length','length threshold'],{sourceKeys:['logic'],tokens:['h'],grammarCards:['quantifier'],formulaCards:['quantifier'],relatedIds:['predicate','greater-or-equal','parameter','finite-domain']});
  add('oriented-area','Oriented area vector','linear',['u×v'],'A planar area together with a chosen normal direction. For the ordered pair u,v in a right-handed Euclidean three-dimensional frame, u×v supplies a normal vector with magnitude equal to the spanned parallelogram area. Reversing the order reverses the normal.','(3,0,0)×(0,2,0)=(0,0,6) has magnitude 6 m² and positive z direction.','oriented area vector',['oriented area','area vector','oriented parallelogram'],{sourceKeys:['cross'],tokens:['u×v'],grammarCards:['cross-product'],formulaCards:['cross-product'],relatedIds:['cross-product','normal-component','right-hand-rule','area','orientation']});
  add('normal-component','Signed normal component','linear',['w_z'],'The signed component of the cross product along the stated positive normal axis. In this planar family it is w_z=‖u‖‖v‖sinθ in square metres. Its magnitude is area; its sign encodes orientation.','For u length 3 m and v length 2 m at −90°, w_z=−6 m² and the area is 6 m².','w subscript z, signed normal component',['signed normal component','normal component','z component','directed normal-area component'],{sourceKeys:['cross'],tokens:['w_z'],lookupAliases:['w_{z}','wᶻ'],grammarCards:['cross-product'],formulaCards:['cross-product'],relatedIds:['cross-product','oriented-area','component','sign','area']});
  add('right-hand-rule','Right-hand rule','linear',[],'The orientation convention selecting u×v in a right-handed orthonormal frame. Curling from u toward v through the smaller nonzero angle aligns the right thumb with the normal; parallel or zero inputs instead give the zero cross product.','A positive quarter turn from the x direction to the y direction gives positive z.','right-hand rule',['right-hand rule','right handed','right-handed','handedness'],{sourceKeys:['cross'],relatedIds:['cross-product','orientation','orthonormal']});
  add('normal-direction-glyphs','Normal-direction drawing symbols','notation',['⊙','⊗'],'In this lesson’s declared drawing convention, a circled dot marks a normal pointing out of the page and a circled cross marks one pointing into it. These glyphs have other roles elsewhere in mathematics; the local legend determines their meaning here.','At a positive 90° turn, the lesson marks positive z with ⊙.','out of the page; into the page',['out of page','into page','out of the page','into the page'],{sourceKeys:['cross'],tokens:['⊙','⊗'],grammarCards:['cross-product'],formulaCards:['cross-product'],relatedIds:['normal-component','right-hand-rule','orientation']});
  add('parallelogram','Parallelogram','geometry',[],'A quadrilateral with opposite sides parallel. The two vectors from a common vertex span a parallelogram, whose area is base times perpendicular height.','Vectors of lengths 3 m and 2 m at 90° span area 6 m².','parallelogram',['parallelogram','spanned parallelogram'],{sourceKeys:['cross'],relatedIds:['area','cross-product','vector-addition','angle']});
  add('equilibrium','Equilibrium of an update rule','dynamics',[],'A state left unchanged by the declared update rule. Stability describes the behavior of nearby starting states; finding an equilibrium alone does not show that nearby states approach it.','Zero is an equilibrium of eₖ₊₁=r eₖ for every allowed r.','equilibrium',['equilibrium','equilibria','fixed state'],{sourceKeys:['scalarDynamics'],relatedIds:['fixed-point','equilibrium-stability','asymptotic-stability','unstable-equilibrium','recurrence']});
  add('fixed-point','Fixed point','dynamics',[],'A value that an update function maps to itself: f(x)=x. It is an equilibrium for the associated discrete dynamical system, but need not be attracting.','For f(e)=1.1e, zero is fixed even though nearby nonzero errors grow.','fixed point',['fixed point','fixed points'],{sourceKeys:['scalarDynamics'],relatedIds:['equilibrium','function','iteration','asymptotic-stability']});
  add('equilibrium-stability','Lyapunov stability','dynamics',[],'An equilibrium is stable to starting-state perturbations when sufficiently nearby starts stay arbitrarily close through all future updates. This is distinct from attraction and from structural stability under perturbations of the rule.','For eₖ₊₁=−eₖ, an error keeps its initial magnitude, so zero is stable but not attracting.','stability of an equilibrium',['Lyapunov stability','Lyapunov stable','stable but not attracting','stability of an equilibrium'],{sourceKeys:['scalarDynamics'],relatedIds:['equilibrium','asymptotic-stability','neutral-stability','unstable-equilibrium','perturbation','structural-stability']});
  add('asymptotic-stability','Asymptotic stability','dynamics',[],'An equilibrium is asymptotically stable when it is stable and nearby initial states approach it as the number of updates tends to infinity. For this scalar linear family, |r|<1 gives decay of every starting error.','For r=−0.5, errors alternate sides and shrink toward zero.','asymptotic stability',['asymptotic stability','asymptotically stable','attracting equilibrium','attraction','attracts'],{sourceKeys:['scalarDynamics'],relatedIds:['equilibrium-stability','convergence','iteration-stability','feedback-multiplier','oscillation']});
  add('neutral-stability','Constant-magnitude boundary cases','dynamics',[],'For eₖ₊₁=r eₖ with |r|=1, the magnitude of each error stays fixed. At r=1 each state is fixed; at r=−1 a nonzero state alternates signs. Both cases are stable but do not attract nonzero errors to zero.','Starting at 1 cm with r=−1 gives 1,−1,1,−1,… cm.','constant-magnitude stability boundary',['neutral','neutral stability','constant-magnitude','no decay','magnitude preserved'],{sourceKeys:['scalarDynamics'],relatedIds:['equilibrium-stability','asymptotic-stability','oscillation','absolute-value']});
  add('unstable-equilibrium','Unstable equilibrium','dynamics',[],'An equilibrium for which arbitrarily small starting-state perturbations can eventually leave some fixed neighborhood. For the scalar linear rule, |r|>1 amplifies every nonzero initial error. Starting exactly at zero does not make the rule stable.','With r=1.1, a starting error of 1 cm becomes 1.1⁸ cm after eight updates and continues growing.','unstable equilibrium',['unstable','unstable equilibrium','instability','amplifies error'],{sourceKeys:['scalarDynamics'],relatedIds:['equilibrium','equilibrium-stability','perturbation','feedback-multiplier']});
  add('structural-stability','Structural stability','dynamics',[],'Persistence of a system’s qualitative behavior under sufficiently small perturbations of its rule, with the class of systems and notion of equivalence specified. Stability of one equilibrium to changes in its starting state does not by itself establish structural stability.','Changing a starting error and changing the update rule are different perturbation questions.','structural stability',['structural stability','rule perturbation','rule perturbations'],{sourceKeys:['structuralDynamics','scalarDynamics'],relatedIds:['equilibrium-stability','perturbation','fixed-point']});
  add('alignment-error','Signed alignment error','dynamics',['e₀','eₖ','eₙ'],'In the correction story, signed displacement from the zero-alignment equilibrium, measured in centimetres. Its sign gives the side of the target; its absolute value gives distance.','An error e₀=−1 cm starts one centimetre on the negative side.','e, the signed alignment error',['alignment error','signed error','signed alignment error','starting error'],{sourceKeys:['scalarDynamics'],tokens:['e₀','eₖ','eₖ₊₁','eₙ'],grammarCards:['stability'],formulaCards:['stability'],relatedIds:['displacement','equilibrium','absolute-value','initial-value','iteration']});
  add('feedback-multiplier','Error multiplier','dynamics',['r'],'The signed factor multiplying the previous error at each correction update. A negative value reverses its side. Its magnitude determines decay, preservation, or growth in this linear model; it is not a retained-volume fraction or probability.','At r=−0.5, an error 1 cm becomes −0.5 cm.','r, the error multiplier',['error multiplier','feedback multiplier','correction multiplier','multiplier per update'],{sourceKeys:['scalarDynamics'],tokens:['r'],grammarCards:['stability'],formulaCards:['stability'],relatedIds:['contraction-factor','asymptotic-stability','neutral-stability','unstable-equilibrium','absolute-value']});
